const App = {
  files: [],
  selected: new Map(), // path -> { path, mode, start, end, tokens }
  collapsedDirs: new Set(),
  browseParent: "",
  goalStep: 1,
  goalFinished: false,
  stage: "goal", // "goal" | "paste"
  appliedLog: [],
  pendingQuestions: [],
  planTasks: [],
  editingPath: "",

  showPopup({ type = "info", title = "", message = "", actions = [] }) {
    const box = document.getElementById("inlinePopup");
    const iconEl = document.getElementById("inlinePopupIcon");
    const titleEl = document.getElementById("inlinePopupTitle");
    const msgEl = document.getElementById("inlinePopupMsg");
    const actEl = document.getElementById("inlinePopupActions");
    if (!box) return;

    box.className = `inline-popup ${type}`;
    const icons = { info: "ℹ️", success: "✅", red: "🚨" };
    iconEl.textContent = icons[type] || "ℹ️";
    titleEl.textContent = title || (type === "red" ? "Action Required: Paste in AI Chat" : "Status");
    msgEl.textContent = message;

    actEl.innerHTML = "";
    actions.forEach((act) => {
      const b = document.createElement("button");
      b.className = `btn ${act.cls || "primary"}`;
      b.textContent = act.label;
      b.onclick = act.onClick;
      actEl.appendChild(b);
    });
  },

  toast(msg, type = "info") {
    this.showPopup({
      type,
      title: type === "success" ? "Completed" : "Status Update",
      message: msg,
    });
  },

  openOptionsModal() {
    document.getElementById("optionsModal").classList.remove("hidden");
  },

  closeOptionsModal() {
    document.getElementById("optionsModal").classList.add("hidden");
  },

  openChoiceModal({ title, description = "", options = [] }) {
    document.getElementById("choiceModalTitle").textContent = title;
    document.getElementById("choiceModalDesc").textContent = description;
    const body = document.getElementById("choiceModalBody");
    body.innerHTML = "";

    options.forEach((opt) => {
      const btn = document.createElement("button");
      btn.className = "choice-option-btn";
      const lbl = document.createElement("span");
      lbl.textContent = opt.label;
      const hint = document.createElement("span");
      hint.className = "muted";
      hint.textContent = opt.hint || "";
      btn.append(lbl, hint);
      btn.onclick = () => {
        this.closeChoiceModal();
        if (opt.onSelect) opt.onSelect();
      };
      body.appendChild(btn);
    });

    document.getElementById("choiceModal").classList.remove("hidden");
  },

  closeChoiceModal() {
    document.getElementById("choiceModal").classList.add("hidden");
  },

  setGoalBadge(stateText, cls = "") {
    const b = document.getElementById("goalBadge");
    b.textContent = `Goal: Step ${this.goalStep} (${stateText})`;
    b.className = `badge goal ${cls}`;
  },

  setStage(stage) {
    this.stage = stage;
    const promptCard = document.getElementById("stagePromptCard");
    const pasteCard = document.getElementById("stagePasteCard");
    const switchBtn = document.getElementById("switchToPasteBtn");

    if (stage === "goal") {
      promptCard.classList.remove("hidden");
      pasteCard.classList.add("hidden");
      if (this.goalStep > 1 || document.getElementById("generatedPrompt").value.trim()) {
        switchBtn.classList.remove("hidden");
      } else {
        switchBtn.classList.add("hidden");
      }
    } else {
      promptCard.classList.add("hidden");
      pasteCard.classList.remove("hidden");
      const pasteArea = document.getElementById("pasteInputArea");
      const doneActions = document.getElementById("doneActions");
      if (this.goalFinished) {
        pasteArea.classList.add("hidden");
        doneActions.classList.remove("hidden");
      } else {
        pasteArea.classList.remove("hidden");
        doneActions.classList.add("hidden");
      }
    }
  },

  togglePromptPreview() {
    document.getElementById("promptPreviewWrap").classList.toggle("hidden");
  },

  resetGoal() {
    this.goalStep = 1;
    this.goalFinished = false;
    this.appliedLog = [];
    this.pendingQuestions = [];
    this.planTasks = [];
    this.selected.clear();

    document.getElementById("task").value = "";
    document.getElementById("generatedPrompt").value = "";
    document.getElementById("promptMeta").textContent = "";
    document.getElementById("copyButtons").innerHTML = "";
    document.getElementById("questionsOut").innerHTML = "";
    document.getElementById("diffOut").innerHTML = "";
    document.getElementById("aiResponse").value = "";
    document.getElementById("applyMeta").textContent = "";
    document.getElementById("promptPreviewWrap").classList.add("hidden");

    const autoPasteChk = document.getElementById("autoProcessPaste");
    const applyBtn = document.getElementById("applyBtn");
    if (applyBtn && autoPasteChk) {
      applyBtn.classList.toggle("hidden", autoPasteChk.checked);
    }

    this.renderPlan([]);
    this.renderFiles();
    this.renderChips();
    this.setGoalBadge("IDLE");
    this.setStage("goal");
    this.showPopup({
      type: "info",
      title: "Ready for a New Goal",
      message: "Describe what you want to build or fix, or double-click any file on the left to inspect/edit.",
    });
  },

  async loadFiles() {
    const res = await fetch("/api/files");
    const data = await res.json();
    this.files = data.files || [];
    this.renderFiles();
  },

  async setProject(customPath = null) {
    const path = customPath !== null ? customPath : document.getElementById("projPath").value;
    const res = await fetch("/api/project", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path }),
    });
    const data = await res.json();
    if (!res.ok) return this.toast(data.error);
    document.getElementById("projPath").value = data.root;
    this.collapsedDirs.clear();
    this.resetGoal();
    await this.loadFiles();
    this.toast("Project loaded");
  },

  async smartSelect() {
    if (this.goalFinished) return;
    const task = document.getElementById("task").value.trim();
    if (!task) return this.toast("Enter a task first so Smart Select can match files.");
    const res = await fetch("/api/smart_select", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ task }),
    });
    const data = await res.json();
    this.selected.clear();
    (data.selected || []).forEach((s) => {
      this.selected.set(s.path, { path: s.path, mode: s.mode, start: "", end: "", tokens: s.tokens || 500 });
    });
    this.renderFiles();
    this.renderChips();
    this.toast(`Smart Select picked ${this.selected.size} file(s)`);
  },

  async openBrowser() {
    document.getElementById("browserModal").classList.remove("hidden");
    await this.browseTo(document.getElementById("projPath").value);
  },

  closeBrowser() {
    document.getElementById("browserModal").classList.add("hidden");
  },

  async browseTo(path) {
    const res = await fetch(`/api/browse?path=${encodeURIComponent(path || "")}`);
    const data = await res.json();
    document.getElementById("browsePath").value = data.current;
    this.browseParent = data.parent || "";
    document.getElementById("upBtn").disabled = !this.browseParent;

    const drives = document.getElementById("driveBar");
    drives.innerHTML = "";
    (data.drives || []).forEach((d) => {
      const b = document.createElement("button");
      b.className = "btn ghost";
      b.textContent = d;
      b.onclick = () => this.browseTo(d);
      drives.appendChild(b);
    });

    const list = document.getElementById("dirList");
    list.innerHTML = "";
    (data.dirs || []).forEach((d) => {
      const row = document.createElement("div");
      row.className = "fitem";
      row.textContent = "📁 " + d.name;
      row.onclick = () => this.browseTo(d.path);
      list.appendChild(row);
    });
  },

  browseUp() {
    if (this.browseParent) this.browseTo(this.browseParent);
  },

  async selectBrowsed() {
    const chosen = document.getElementById("browsePath").value;
    this.closeBrowser();
    await this.setProject(chosen);
  },

  buildFileTree(files) {
    const root = { name: "", path: "", folders: new Map(), files: [] };
    files.forEach((f) => {
      const parts = f.path.split("/");
      let node = root;
      for (let i = 0; i < parts.length - 1; i++) {
        const seg = parts[i];
        const nextPath = node.path ? `${node.path}/${seg}` : seg;
        if (!node.folders.has(seg)) {
          node.folders.set(seg, { name: seg, path: nextPath, folders: new Map(), files: [] });
        }
        node = node.folders.get(seg);
      }
      node.files.push({ ...f, name: parts[parts.length - 1] });
    });
    return root;
  },

  collectFolderFiles(node, acc = []) {
    node.files.forEach((f) => acc.push(f));
    node.folders.forEach((sub) => this.collectFolderFiles(sub, acc));
    return acc;
  },

  renderTreeNode(node, container, isFilterActive) {
    const sortedFolders = Array.from(node.folders.values()).sort((a, b) => a.name.localeCompare(b.name));
    sortedFolders.forEach((folder) => {
      const descendantFiles = this.collectFolderFiles(folder, []);
      if (!descendantFiles.length) return;

      const wrap = document.createElement("div");
      wrap.className = "tree-folder";

      const row = document.createElement("div");
      row.className = "tree-row";

      const isCollapsed = !isFilterActive && this.collapsedDirs.has(folder.path);
      const caret = document.createElement("span");
      caret.className = "tree-caret";
      caret.textContent = isCollapsed ? "▸" : "▾";

      const cb = document.createElement("input");
      cb.type = "checkbox";
      const selectedCount = descendantFiles.filter((f) => this.selected.has(f.path)).length;
      cb.checked = selectedCount > 0 && selectedCount === descendantFiles.length;
      cb.indeterminate = selectedCount > 0 && selectedCount < descendantFiles.length;
      cb.onclick = (e) => e.stopPropagation();
      cb.onchange = () => {
        descendantFiles.forEach((f) => {
          if (cb.checked) {
            const mode = f.est_tokens > 4000 ? "outline" : "full";
            this.selected.set(f.path, { path: f.path, mode, start: "", end: "", tokens: f.est_tokens });
          } else {
            this.selected.delete(f.path);
          }
        });
        this.renderFiles();
        this.renderChips();
      };

      const lbl = document.createElement("span");
      lbl.className = "tree-folder-lbl";
      lbl.textContent = `📁 ${folder.name}`;

      row.onclick = () => {
        if (this.collapsedDirs.has(folder.path)) {
          this.collapsedDirs.delete(folder.path);
        } else {
          this.collapsedDirs.add(folder.path);
        }
        this.renderFiles();
      };

      row.append(caret, cb, lbl);
      wrap.appendChild(row);

      const childrenBox = document.createElement("div");
      childrenBox.className = `tree-children${isCollapsed ? " collapsed" : ""}`;
      this.renderTreeNode(folder, childrenBox, isFilterActive);
      wrap.appendChild(childrenBox);
      container.appendChild(wrap);
    });

    const sortedFiles = [...node.files].sort((a, b) => a.name.localeCompare(b.name));
    sortedFiles.forEach((f) => {
      const row = document.createElement("div");
      row.className = "tree-row";
      row.title = "Double-click to view or edit file";

      const spacer = document.createElement("span");
      spacer.className = "tree-caret";
      spacer.textContent = "";

      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.checked = this.selected.has(f.path);
      cb.onclick = (e) => e.stopPropagation();
      cb.onchange = () => {
        if (cb.checked) {
          const defaultMode = f.est_tokens > 4000 ? "outline" : "full";
          this.selected.set(f.path, { path: f.path, mode: defaultMode, start: "", end: "", tokens: f.est_tokens });
        } else {
          this.selected.delete(f.path);
        }
        this.renderFiles();
        this.renderChips();
      };

      const name = document.createElement("span");
      name.className = "tree-file-lbl";
      name.textContent = f.name;

      const meta = document.createElement("span");
      meta.className = "fmeta";
      meta.textContent = `~${f.est_tokens}t`;

      row.onclick = () => {
        cb.checked = !cb.checked;
        cb.onchange();
      };
      row.ondblclick = (e) => {
        e.stopPropagation();
        this.openEditor(f.path);
      };

      row.append(spacer, cb, name, meta);
      container.appendChild(row);
    });
  },

  renderFiles() {
    const q = document.getElementById("filter").value.toLowerCase().trim();
    const list = document.getElementById("fileList");
    list.innerHTML = "";

    const filtered = q
      ? this.files.filter((f) => f.path.toLowerCase().includes(q))
      : this.files;

    const tree = this.buildFileTree(filtered);
    this.renderTreeNode(tree, list, Boolean(q));
    this.updateStats();
  },

  renderChips() {
    const box = document.getElementById("selectedChips");
    box.innerHTML = "";
    this.selected.forEach((spec, path) => {
      const chip = document.createElement("div");
      chip.className = "chip";
      const lbl = document.createElement("span");
      lbl.textContent = path;

      const modeBtn = document.createElement("button");
      modeBtn.className = "btn ghost";
      modeBtn.style.padding = "2px 8px";
      modeBtn.style.fontSize = "11px";
      modeBtn.textContent = `${spec.mode} ▾`;
      modeBtn.onclick = () => {
        this.openChoiceModal({
          title: `Context Mode for ${path}`,
          description: "Choose how much of this file to include in the AI prompt:",
          options: [
            {
              label: "Full File",
              hint: `~${spec.tokens} tokens`,
              onSelect: () => {
                spec.mode = "full";
                this.renderChips();
                this.updateStats();
                this.toast(`${path} set to full mode`);
              },
            },
            {
              label: "Outline Only (Save ~80% Tokens)",
              hint: `~${Math.round(spec.tokens * 0.2)} tokens`,
              onSelect: () => {
                spec.mode = "outline";
                this.renderChips();
                this.updateStats();
                this.toast(`${path} set to outline mode`);
              },
            },
            {
              label: "Specific Line Range",
              hint: "Choose start & end lines",
              onSelect: () => {
                spec.mode = "range";
                this.renderChips();
                this.updateStats();
              },
            },
            {
              label: "Remove File from Selection",
              hint: "Exclude",
              onSelect: () => {
                this.selected.delete(path);
                this.renderFiles();
                this.renderChips();
              },
            },
          ],
        });
      };
      chip.append(lbl, modeBtn);

      if (spec.mode === "range") {
        const sIn = document.createElement("input");
        sIn.className = "rng";
        sIn.placeholder = "start";
        sIn.value = spec.start;
        sIn.oninput = () => (spec.start = parseInt(sIn.value) || "");
        const eIn = document.createElement("input");
        eIn.className = "rng";
        eIn.placeholder = "end";
        eIn.value = spec.end;
        eIn.oninput = () => (spec.end = parseInt(eIn.value) || "");
        chip.append(sIn, eIn);
      }
      box.appendChild(chip);
    });
  },

  updateStats() {
    document.getElementById("fileStats").textContent = `${this.selected.size} / ${this.files.length} files`;
    let total = 0;
    this.selected.forEach((s) => {
      total += s.mode === "outline" ? Math.round(s.tokens * 0.2) : s.tokens;
    });
    document.getElementById("selectedTokens").textContent = `~${total.toLocaleString()} tokens`;
  },

  toggleAll(on) {
    const q = document.getElementById("filter").value.toLowerCase();
    this.files.forEach((f) => {
      if (!q || f.path.toLowerCase().includes(q)) {
        if (on) {
          const mode = f.est_tokens > 4000 ? "outline" : "full";
          this.selected.set(f.path, { path: f.path, mode, start: "", end: "", tokens: f.est_tokens });
        } else {
          this.selected.delete(f.path);
        }
      }
    });
    this.renderFiles();
    this.renderChips();
  },

  collectAnswers() {
    const answers = [];
    this.pendingQuestions.forEach((q, idx) => {
      const checked = document.querySelector(`input[name="qa_${idx}"]:checked`);
      const custom = document.getElementById(`qa_custom_${idx}`).value.trim();
      const ans = custom || (checked ? checked.value : "");
      if (ans) answers.push({ question: q.question, answer: ans });
    });
    return answers;
  },

  renderPlan(planItems) {
    const panel = document.getElementById("planPanel");
    const box = document.getElementById("planOut");
    const meta = document.getElementById("planMeta");

    if (planItems && planItems.length) {
      this.planTasks = planItems;
    }

    if (!this.planTasks.length) {
      panel.classList.add("hidden");
      panel.open = false;
      box.innerHTML = "";
      return;
    }

    panel.classList.remove("hidden");
    box.innerHTML = "";
    let totalCount = 0;
    let doneCount = 0;

    this.planTasks.forEach((item) => {
      totalCount += 1;
      if (item.done) doneCount += 1;

      const wrap = document.createElement("div");
      wrap.className = "plan-item";

      const mainRow = document.createElement("label");
      mainRow.className = "plan-main";
      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.style.width = "auto";
      cb.checked = Boolean(item.done);
      const txt = document.createElement("span");
      txt.textContent = item.text;
      if (item.done) txt.className = "plan-done";
      cb.onchange = () => {
        item.done = cb.checked;
        txt.className = cb.checked ? "plan-done" : "";
      };
      mainRow.append(cb, txt);
      wrap.appendChild(mainRow);

      if (item.subtasks && item.subtasks.length) {
        const subBox = document.createElement("div");
        subBox.className = "plan-sublist";
        item.subtasks.forEach((sub) => {
          totalCount += 1;
          if (sub.done) doneCount += 1;
          const subRow = document.createElement("label");
          subRow.className = "plan-sub";
          const scb = document.createElement("input");
          scb.type = "checkbox";
          scb.style.width = "auto";
          scb.checked = Boolean(sub.done);
          const stxt = document.createElement("span");
          stxt.textContent = sub.text;
          if (sub.done) stxt.className = "plan-done";
          scb.onchange = () => {
            sub.done = scb.checked;
            stxt.className = scb.checked ? "plan-done" : "";
          };
          subRow.append(scb, stxt);
          subBox.appendChild(subRow);
        });
        wrap.appendChild(subBox);
      }
      box.appendChild(wrap);
    });

    meta.textContent = `${doneCount}/${totalCount} completed (click to expand)`;
  },

  async buildPrompt(isAutoNext = false) {
    const task = document.getElementById("task").value.trim();
    if (!task) return this.toast("Describe your goal first.");

    this.goalFinished = false;

    if (
      !isAutoNext &&
      this.goalStep === 1 &&
      this.selected.size === 0 &&
      document.getElementById("autoSelectSmart").checked
    ) {
      await this.smartSelect();
    }

    const include_tree = document.getElementById("includeTree").checked;
    const chunk_size = parseInt(document.getElementById("chunkSize").value) || 120000;
    const files = Array.from(this.selected.values());
    const answers = this.collectAnswers();

    const res = await fetch("/api/build_prompt", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        task,
        files,
        include_tree,
        chunk_size,
        goal_step: this.goalStep,
        answers,
        applied_log: this.appliedLog,
      }),
    });
    const data = await res.json();
    document.getElementById("generatedPrompt").value = data.full_prompt;
    document.getElementById("promptMeta").textContent =
      `${data.chars.toLocaleString()} chars (~${data.est_tokens.toLocaleString()} tokens)`;

    const btns = document.getElementById("copyButtons");
    btns.innerHTML = "";
    data.parts.forEach((part, idx) => {
      const b = document.createElement("button");
      b.className = "btn success";
      const label = data.parts.length === 1 ? "Copy Prompt" : `Copy Part ${idx + 1}/${data.parts.length}`;
      b.textContent = label;
      b.onclick = async () => {
        await navigator.clipboard.writeText(part);
        this.toast(`${label} copied!`);
        if (document.getElementById("autoUnselect").checked) {
          this.selected.clear();
          this.renderFiles();
          this.renderChips();
        }
      };
      btns.appendChild(b);
    });

    const triggerAiHandoffPopup = (copiedOk) => {
      const firstLabel = data.parts.length === 1 ? "Prompt" : `Part 1/${data.parts.length}`;
      this.showPopup({
        type: "red",
        title: copiedOk
          ? `${firstLabel} Copied — Go Paste in AI & Copy Reply`
          : "Prompt Ready — Copy & Paste in AI Chat",
        message: "1) Paste the prompt into your AI chat. 2) Copy the AI's response. 3) Click Done below to auto-apply and advance.",
        actions: [
          {
            label: "Copy Prompt Again",
            cls: "ghost",
            onClick: async () => {
              await navigator.clipboard.writeText(data.parts[0]);
              triggerAiHandoffPopup(true);
            },
          },
          {
            label: "Done (Paste & Run Next Step)",
            cls: "danger",
            onClick: async () => {
              const aiBox = document.getElementById("aiResponse");
              this.setStage("paste");
              try {
                const clipText = await navigator.clipboard.readText();
                if (clipText && clipText.trim() && clipText.trim() !== data.parts[0].trim()) {
                  aiBox.value = clipText;
                  await this.runOps(true);
                  return;
                }
              } catch (e) {
                // Fallback if clipboard read permission is blocked
              }
              if (aiBox.value.trim()) {
                await this.runOps(true);
              } else {
                aiBox.focus();
                this.showPopup({
                  type: "red",
                  title: "Paste AI Response Below",
                  message: "Press Ctrl+V inside the response box (or copy the AI reply first and click Done again).",
                });
              }
            },
          },
        ],
      });
    };

    if (data.parts && data.parts.length > 0) {
      try {
        await navigator.clipboard.writeText(data.parts[0]);
        if (document.getElementById("autoUnselect").checked) {
          this.selected.clear();
          this.renderFiles();
          this.renderChips();
        }
        triggerAiHandoffPopup(true);
      } catch (e) {
        triggerAiHandoffPopup(false);
      }
    }

    this.setGoalBadge("WAITING REPLY", "active");
    this.setStage("paste");
  },

  renderQuestions(questions) {
    this.pendingQuestions = questions || [];
    const box = document.getElementById("questionsOut");
    box.innerHTML = "";
    if (!this.pendingQuestions.length) return;

    this.pendingQuestions.forEach((q, idx) => {
      const card = document.createElement("div");
      card.className = "qa-card";
      const title = document.createElement("div");
      title.className = "qa-title";
      title.textContent = q.question;
      card.appendChild(title);

      (q.options || []).forEach((opt) => {
        const lbl = document.createElement("label");
        lbl.className = "qa-opt";
        const r = document.createElement("input");
        r.type = "radio";
        r.name = `qa_${idx}`;
        r.value = opt;
        r.onchange = () => {
          if (this.pendingQuestions.length === 1) {
            this.submitAnswersAndAdvance();
          }
        };
        lbl.append(r, document.createTextNode(opt));
        card.appendChild(lbl);
      });

      const custom = document.createElement("input");
      custom.id = `qa_custom_${idx}`;
      custom.placeholder = "Or type a custom answer and press Enter...";
      custom.onkeydown = (e) => {
        if (e.key === "Enter") {
          e.preventDefault();
          this.submitAnswersAndAdvance();
        }
      };
      card.appendChild(custom);
      box.appendChild(card);
    });

    const submitRow = document.createElement("div");
    submitRow.className = "row";
    const btn = document.createElement("button");
    btn.className = "btn primary";
    btn.textContent = "Send Answers & Copy Next Prompt →";
    btn.onclick = () => this.submitAnswersAndAdvance();
    submitRow.appendChild(btn);
    box.appendChild(submitRow);
  },

  async submitAnswersAndAdvance() {
    this.goalStep += 1;
    await this.buildPrompt(true);
    document.getElementById("aiResponse").value = "";
    this.renderQuestions([]);
    this.toast(`Step ${this.goalStep} prompt with answers copied!`);
  },

  async runOps(apply) {
    const text = document.getElementById("aiResponse").value;
    let fallback_path = document.getElementById("fallbackFile").value.trim();
    if (!fallback_path && this.selected.size === 1) {
      fallback_path = Array.from(this.selected.keys())[0];
    }

    const res = await fetch("/api/apply", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text, apply, fallback_path }),
    });
    const data = await res.json();

    if (data.plan && data.plan.length) {
      this.renderPlan(data.plan);
    }

    const hasQuestions = (data.questions || []).length > 0;
    const hasNeedFiles = (data.need_files || []).length > 0;

    this.renderQuestions(data.questions || []);

    const out = document.getElementById("diffOut");
    out.innerHTML = "";
    const results = data.results || [];
    document.getElementById("applyMeta").textContent =
      `${results.length} edit(s) · ${(data.need_files || []).length} file req(s) · ${(data.questions || []).length} question(s)`;

    let appliedCount = 0;
    let errorCount = 0;
    results.forEach((r) => {
      const isApplied = apply && r.status === "applied";
      const card = document.createElement("details");
      card.className = "diff-file";
      card.open = !isApplied;

      const hdr = document.createElement("summary");
      hdr.className = `diff-header ${r.status}`;
      hdr.style.cursor = "pointer";
      hdr.textContent = `${isApplied ? "▸" : "▾"} [${r.status.toUpperCase()}] ${r.path}`;
      card.ontoggle = () => {
        hdr.textContent = `${card.open ? "▾" : "▸"} [${r.status.toUpperCase()}] ${r.path}`;
      };
      card.appendChild(hdr);

      const body = document.createElement("div");
      body.className = "diff-body";
      if (r.message) {
        const line = document.createElement("div");
        line.className = "dline del";
        line.textContent = r.message;
        body.appendChild(line);
      } else if (r.diff_lines && r.diff_lines.length) {
        r.diff_lines.forEach((dl) => {
          const line = document.createElement("div");
          line.className = `dline ${dl.kind}`;
          line.textContent = dl.text;
          body.appendChild(line);
        });
      } else {
        const line = document.createElement("div");
        line.className = "dline meta";
        line.textContent = "(no text changes)";
        body.appendChild(line);
      }
      card.appendChild(body);
      out.appendChild(card);

      if (isApplied) {
        appliedCount += 1;
        this.appliedLog.push(`Step ${this.goalStep}: updated ${r.path}`);
      } else if (r.status === "error") {
        errorCount += 1;
      }
    });

    const applyBtn = document.getElementById("applyBtn");
    if (applyBtn) {
      const autoOn = document.getElementById("autoProcessPaste").checked;
      applyBtn.classList.toggle("hidden", autoOn && appliedCount > 0 && errorCount === 0);
    }

    if (apply && appliedCount > 0) {
      await this.loadFiles();
    }

    // Handle AI-requested files automatically
    if (hasNeedFiles) {
      data.need_files.forEach((nf) => {
        const match = this.files.find((f) => f.path === nf.path);
        this.selected.set(nf.path, {
          path: nf.path,
          mode: nf.mode || "full",
          start: nf.start || "",
          end: nf.end || "",
          tokens: match ? match.est_tokens : 500,
        });
      });
      this.renderFiles();
      this.renderChips();

      if (!hasQuestions) {
        this.goalStep += 1;
        await this.buildPrompt(true);
        document.getElementById("aiResponse").value = "";
        this.setGoalBadge("WAITING NEXT", "active");
        this.toast(`Step ${this.goalStep}: copied ${data.need_files.length} requested file(s)!`);
        return;
      }
    }

    // Automatically advance to next step when AI indicates APPLIED_NEXT
    if (apply && data.status_flag === "APPLIED_NEXT" && !hasQuestions && errorCount === 0) {
      this.goalStep += 1;
      await this.buildPrompt(true);
      document.getElementById("aiResponse").value = "";
      this.setGoalBadge("WAITING NEXT", "active");
      this.toast(`Applied ${appliedCount} file(s) & copied Step ${this.goalStep} prompt!`);
      return;
    }

    if (data.status_flag === "DONE") {
      this.goalFinished = true;
      this.selected.clear();
      this.renderFiles();
      this.renderChips();
      this.setGoalBadge("DONE", "done");
      this.setStage("paste");
      this.showPopup({
        type: "success",
        title: "Goal Completed!",
        message: appliedCount > 0
          ? `Successfully applied ${appliedCount} file(s). Expand any file below to review its diff.`
          : "All steps for this goal are complete.",
        actions: [
          {
            label: "Start New Goal",
            cls: "success",
            onClick: () => this.resetGoal(),
          },
        ],
      });
    } else if (hasQuestions || data.status_flag === "NEED_MORE" || data.status_flag === "APPLIED_NEXT") {
      this.setGoalBadge("WAITING INPUT", "active");
      if (hasQuestions) {
        this.showPopup({
          type: "info",
          title: "AI Needs Your Input",
          message: "Choose an option below (or type a custom answer) to generate and copy the next prompt.",
        });
      }
    } else if (apply && appliedCount > 0) {
      this.showPopup({
        type: "success",
        title: `Applied ${appliedCount} File(s)`,
        message: "Changes saved to disk. Expand any file below to inspect the diff.",
      });
    } else if (errorCount > 0) {
      this.showPopup({
        type: "red",
        title: "Patch Error",
        message: "One or more edits could not be applied. Check the details below.",
      });
    }
  },

  // Code Editor Modal
  async openEditor(relPath) {
    const res = await fetch(`/api/file?path=${encodeURIComponent(relPath)}`);
    const data = await res.json();
    if (!res.ok) return this.toast(data.error || "Failed to open file");

    this.editingPath = relPath;
    document.getElementById("editorTitle").textContent = relPath;
    const ext = relPath.includes(".") ? relPath.split(".").pop().toUpperCase() : "TEXT";
    document.getElementById("editorLangBadge").textContent = ext;

    const area = document.getElementById("editorCode");
    area.value = data.content;
    this.syncEditorGutter();
    document.getElementById("editorModal").classList.remove("hidden");
    area.focus();
  },

  closeEditor() {
    document.getElementById("editorModal").classList.add("hidden");
    this.editingPath = "";
  },

  syncEditorGutter() {
    const area = document.getElementById("editorCode");
    const gutter = document.getElementById("editorLines");
    const lineCount = (area.value.match(/\n/g) || []).length + 1;
    const nums = [];
    for (let i = 1; i <= lineCount; i++) nums.push(i);
    gutter.textContent = nums.join("\n");
  },

  syncEditorScroll() {
    const area = document.getElementById("editorCode");
    const gutter = document.getElementById("editorLines");
    gutter.scrollTop = area.scrollTop;
  },

  prettifyEditor() {
    const area = document.getElementById("editorCode");
    const ext = this.editingPath.split(".").pop().toLowerCase();
    try {
      if (ext === "json") {
        area.value = JSON.stringify(JSON.parse(area.value), null, 2);
        this.syncEditorGutter();
        return this.toast("Formatted JSON");
      }
      // Clean trailing spaces, normalize tabs to 2/4 spaces, and ensure single trailing newline
      const indent = ext === "py" ? "    " : "  ";
      const cleaned = area.value
        .replace(/\r\n/g, "\n")
        .split("\n")
        .map((line) => line.replace(/\t/g, indent).replace(/[ \t]+$/, ""))
        .join("\n")
        .replace(/\n{3,}/g, "\n\n")
        .trimEnd() + "\n";
      area.value = cleaned;
      this.syncEditorGutter();
      this.toast("Prettified whitespace & indentation");
    } catch (e) {
      this.toast(`Format error: ${e.message}`);
    }
  },

  async saveEditor() {
    if (!this.editingPath) return;
    const content = document.getElementById("editorCode").value;
    const res = await fetch("/api/file", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path: this.editingPath, content }),
    });
    const data = await res.json();
    if (!res.ok) return this.toast(data.error || "Save failed");
    await this.loadFiles();
    this.toast(`Saved ${this.editingPath}`);
  },

  init() {
    // Clear browser-restored form inputs on page reload so Smart Select never auto-picks stale goals
    document.getElementById("task").value = "";
    document.getElementById("aiResponse").value = "";
    document.getElementById("generatedPrompt").value = "";
    document.getElementById("fallbackFile").value = "";
    this.setStage("goal");

    const autoPasteChk = document.getElementById("autoProcessPaste");
    const applyBtn = document.getElementById("applyBtn");
    const syncApplyBtnVisibility = () => {
      if (applyBtn) applyBtn.classList.toggle("hidden", autoPasteChk.checked);
    };
    syncApplyBtnVisibility();
    autoPasteChk.addEventListener("change", syncApplyBtnVisibility);

    const aiBox = document.getElementById("aiResponse");
    aiBox.addEventListener("paste", () => {
      if (!autoPasteChk.checked) return;
      setTimeout(() => {
        if (aiBox.value.trim()) this.runOps(true);
      }, 60);
    });

    const taskBox = document.getElementById("task");
    let smartTimer = null;
    taskBox.addEventListener("input", () => {
      if (this.goalFinished) this.goalFinished = false;
      if (!document.getElementById("autoSelectSmart").checked) return;
      clearTimeout(smartTimer);
      smartTimer = setTimeout(() => {
        if (
          this.stage === "goal" &&
          !this.goalFinished &&
          this.goalStep === 1 &&
          taskBox.value.trim().length >= 8 &&
          this.selected.size === 0
        ) {
          this.smartSelect();
        }
      }, 650);
    });

    const editorArea = document.getElementById("editorCode");
    editorArea.addEventListener("keydown", (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "s") {
        e.preventDefault();
        this.saveEditor();
      } else if (e.key === "Tab") {
        e.preventDefault();
        const start = editorArea.selectionStart;
        const end = editorArea.selectionEnd;
        const indent = this.editingPath.endsWith(".py") ? "    " : "  ";
        editorArea.value = editorArea.value.substring(0, start) + indent + editorArea.value.substring(end);
        editorArea.selectionStart = editorArea.selectionEnd = start + indent.length;
        this.syncEditorGutter();
      }
    });
  },
};

App.init();
App.loadFiles();

const App = {
  files: [],
  selected: new Map(), // path -> { path, mode, start, end, tokens }
  expandedDirs: new Set(),
  browseParent: "",
  goalStep: 1,
  goalFinished: false,
  stage: "goal", // "goal" | "paste"
  appliedLog: [],
  pendingQuestions: [],
  planTasks: [],
  editingPath: "",

  showPopup({ type = "info", title = "", message = "", actions = [] }) {
    const box = document.getElementById("inlinePopup");
    const iconEl = document.getElementById("inlinePopupIcon");
    const titleEl = document.getElementById("inlinePopupTitle");
    const msgEl = document.getElementById("inlinePopupMsg");
    const actEl = document.getElementById("inlinePopupActions");
    if (!box) return;

    box.className = `inline-popup ${type}`;
    const icons = { info: "ℹ️", success: "✅", red: "🚨" };
    iconEl.textContent = icons[type] || "ℹ️";
    titleEl.textContent = title || (type === "red" ? "Action Required: Paste in AI Chat" : "Status");
    msgEl.textContent = message;

    actEl.innerHTML = "";
    actions.forEach((act) => {
      const b = document.createElement("button");
      b.className = `btn ${act.cls || "primary"}`;
      b.textContent = act.label;
      b.onclick = act.onClick;
      actEl.appendChild(b);
    });
  },

  toast(msg, type = "info") {
    this.showPopup({
      type,
      title: type === "success" ? "Completed" : "Status Update",
      message: msg,
    });
  },

  openOptionsModal() {
    document.getElementById("optionsModal").classList.remove("hidden");
  },

  closeOptionsModal() {
    document.getElementById("optionsModal").classList.add("hidden");
  },

  openChoiceModal({ title, description = "", options = [] }) {
    document.getElementById("choiceModalTitle").textContent = title;
    document.getElementById("choiceModalDesc").textContent = description;
    const body = document.getElementById("choiceModalBody");
    body.innerHTML = "";

    options.forEach((opt) => {
      const btn = document.createElement("button");
      btn.className = "choice-option-btn";
      const lbl = document.createElement("span");
      lbl.textContent = opt.label;
      const hint = document.createElement("span");
      hint.className = "muted";
      hint.textContent = opt.hint || "";
      btn.append(lbl, hint);
      btn.onclick = () => {
        this.closeChoiceModal();
        if (opt.onSelect) opt.onSelect();
      };
      body.appendChild(btn);
    });

    document.getElementById("choiceModal").classList.remove("hidden");
  },

  closeChoiceModal() {
    document.getElementById("choiceModal").classList.add("hidden");
  },

  setGoalBadge(stateText, cls = "") {
    const b = document.getElementById("goalBadge");
    b.textContent = `Goal: Step ${this.goalStep} (${stateText})`;
    b.className = `badge goal ${cls}`;
  },

  setStage(stage) {
    this.stage = stage;
    const promptCard = document.getElementById("stagePromptCard");
    const pasteCard = document.getElementById("stagePasteCard");
    const switchBtn = document.getElementById("switchToPasteBtn");

    if (stage === "goal") {
      promptCard.classList.remove("hidden");
      pasteCard.classList.add("hidden");
      if (this.goalStep > 1 || document.getElementById("generatedPrompt").value.trim()) {
        switchBtn.classList.remove("hidden");
      } else {
        switchBtn.classList.add("hidden");
      }
    } else {
      promptCard.classList.add("hidden");
      pasteCard.classList.remove("hidden");
      const pasteArea = document.getElementById("pasteInputArea");
      const doneActions = document.getElementById("doneActions");
      if (this.goalFinished) {
        pasteArea.classList.add("hidden");
        doneActions.classList.remove("hidden");
      } else {
        pasteArea.classList.remove("hidden");
        doneActions.classList.add("hidden");
      }
    }
  },

  togglePromptPreview() {
    document.getElementById("promptPreviewWrap").classList.toggle("hidden");
  },

  resetGoal() {
    this.goalStep = 1;
    this.goalFinished = false;
    this.appliedLog = [];
    this.pendingQuestions = [];
    this.planTasks = [];
    this.selected.clear();

    document.getElementById("task").value = "";
    document.getElementById("generatedPrompt").value = "";
    document.getElementById("promptMeta").textContent = "";
    document.getElementById("copyButtons").innerHTML = "";
    document.getElementById("questionsOut").innerHTML = "";
    document.getElementById("diffOut").innerHTML = "";
    document.getElementById("aiResponse").value = "";
    document.getElementById("applyMeta").textContent = "";
    document.getElementById("promptPreviewWrap").classList.add("hidden");

    const autoPasteChk = document.getElementById("autoProcessPaste");
    const applyBtn = document.getElementById("applyBtn");
    if (applyBtn && autoPasteChk) {
      applyBtn.classList.toggle("hidden", autoPasteChk.checked);
    }

    this.renderPlan([]);
    this.renderFiles();
    this.renderChips();
    this.setGoalBadge("IDLE");
    this.setStage("goal");
    this.showPopup({
      type: "info",
      title: "Ready for a New Goal",
      message: "Describe what you want to build or fix, or double-click any file on the left to inspect/edit.",
    });
  },

  async loadFiles() {
    const res = await fetch("/api/files");
    const data = await res.json();
    this.files = data.files || [];
    this.renderFiles();
  },

  async setProject(customPath = null) {
    const path = customPath !== null ? customPath : document.getElementById("projPath").value;
    const res = await fetch("/api/project", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path }),
    });
    const data = await res.json();
    if (!res.ok) return this.toast(data.error);
    document.getElementById("projPath").value = data.root;
    this.collapsedDirs.clear();
    this.resetGoal();
    await this.loadFiles();
    this.toast("Project loaded");
  },

  async smartSelect() {
    if (this.goalFinished) return;
    const task = document.getElementById("task").value.trim();
    if (!task) return this.toast("Enter a task first so Smart Select can match files.");
    const res = await fetch("/api/smart_select", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ task }),
    });
    const data = await res.json();
    this.selected.clear();
    (data.selected || []).forEach((s) => {
      this.selected.set(s.path, { path: s.path, mode: s.mode, start: "", end: "", tokens: s.tokens || 500 });
    });
    this.renderFiles();
    this.renderChips();
    this.toast(`Smart Select picked ${this.selected.size} file(s)`);
  },

  async openBrowser() {
    document.getElementById("browserModal").classList.remove("hidden");
    await this.browseTo(document.getElementById("projPath").value);
  },

  closeBrowser() {
    document.getElementById("browserModal").classList.add("hidden");
  },

  async browseTo(path) {
    const res = await fetch(`/api/browse?path=${encodeURIComponent(path || "")}`);
    const data = await res.json();
    document.getElementById("browsePath").value = data.current;
    this.browseParent = data.parent || "";
    document.getElementById("upBtn").disabled = !this.browseParent;

    const drives = document.getElementById("driveBar");
    drives.innerHTML = "";
    (data.drives || []).forEach((d) => {
      const b = document.createElement("button");
      b.className = "btn ghost";
      b.textContent = d;
      b.onclick = () => this.browseTo(d);
      drives.appendChild(b);
    });

    const list = document.getElementById("dirList");
    list.innerHTML = "";
    (data.dirs || []).forEach((d) => {
      const row = document.createElement("div");
      row.className = "fitem";
      row.textContent = "📁 " + d.name;
      row.onclick = () => this.browseTo(d.path);
      list.appendChild(row);
    });
  },

  browseUp() {
    if (this.browseParent) this.browseTo(this.browseParent);
  },

  async selectBrowsed() {
    const chosen = document.getElementById("browsePath").value;
    this.closeBrowser();
    await this.setProject(chosen);
  },

  buildFileTree(files) {
    const root = { name: "", path: "", folders: new Map(), files: [] };
    files.forEach((f) => {
      const parts = f.path.split("/");
      let node = root;
      for (let i = 0; i < parts.length - 1; i++) {
        const seg = parts[i];
        const nextPath = node.path ? `${node.path}/${seg}` : seg;
        if (!node.folders.has(seg)) {
          node.folders.set(seg, { name: seg, path: nextPath, folders: new Map(), files: [] });
        }
        node = node.folders.get(seg);
      }
      node.files.push({ ...f, name: parts[parts.length - 1] });
    });
    return root;
  },

  collectFolderFiles(node, acc = []) {
    node.files.forEach((f) => acc.push(f));
    node.folders.forEach((sub) => this.collectFolderFiles(sub, acc));
    return acc;
  },

  renderTreeNode(node, container, isFilterActive) {
    const sortedFolders = Array.from(node.folders.values()).sort((a, b) => a.name.localeCompare(b.name));
    sortedFolders.forEach((folder) => {
      const descendantFiles = this.collectFolderFiles(folder, []);
      if (!descendantFiles.length) return;

      const wrap = document.createElement("div");
      wrap.className = "tree-folder";

      const row = document.createElement("div");
      row.className = "tree-row";

      const isCollapsed = !isFilterActive && this.collapsedDirs.has(folder.path);
      const caret = document.createElement("span");
      caret.className = "tree-caret";
      caret.textContent = isCollapsed ? "▸" : "▾";

      const cb = document.createElement("input");
      cb.type = "checkbox";
      const selectedCount = descendantFiles.filter((f) => this.selected.has(f.path)).length;
      cb.checked = selectedCount > 0 && selectedCount === descendantFiles.length;
      cb.indeterminate = selectedCount > 0 && selectedCount < descendantFiles.length;
      cb.onclick = (e) => e.stopPropagation();
      cb.onchange = () => {
        descendantFiles.forEach((f) => {
          if (cb.checked) {
            const mode = f.est_tokens > 4000 ? "outline" : "full";
            this.selected.set(f.path, { path: f.path, mode, start: "", end: "", tokens: f.est_tokens });
          } else {
            this.selected.delete(f.path);
          }
        });
        this.renderFiles();
        this.renderChips();
      };

      const lbl = document.createElement("span");
      lbl.className = "tree-folder-lbl";
      lbl.textContent = `📁 ${folder.name}`;

      row.onclick = () => {
        if (this.collapsedDirs.has(folder.path)) {
          this.collapsedDirs.delete(folder.path);
        } else {
          this.collapsedDirs.add(folder.path);
        }
        this.renderFiles();
      };

      row.append(caret, cb, lbl);
      wrap.appendChild(row);

      const childrenBox = document.createElement("div");
      childrenBox.className = `tree-children${isCollapsed ? " collapsed" : ""}`;
      this.renderTreeNode(folder, childrenBox, isFilterActive);
      wrap.appendChild(childrenBox);
      container.appendChild(wrap);
    });

    const sortedFiles = [...node.files].sort((a, b) => a.name.localeCompare(b.name));
    sortedFiles.forEach((f) => {
      const row = document.createElement("div");
      row.className = "tree-row";
      row.title = "Double-click to view or edit file";

      const spacer = document.createElement("span");
      spacer.className = "tree-caret";
      spacer.textContent = "";

      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.checked = this.selected.has(f.path);
      cb.onclick = (e) => e.stopPropagation();
      cb.onchange = () => {
        if (cb.checked) {
          const defaultMode = f.est_tokens > 4000 ? "outline" : "full";
          this.selected.set(f.path, { path: f.path, mode: defaultMode, start: "", end: "", tokens: f.est_tokens });
        } else {
          this.selected.delete(f.path);
        }
        this.renderFiles();
        this.renderChips();
      };

      const name = document.createElement("span");
      name.className = "tree-file-lbl";
      name.textContent = f.name;

      const meta = document.createElement("span");
      meta.className = "fmeta";
      meta.textContent = `~${f.est_tokens}t`;

      row.onclick = () => {
        cb.checked = !cb.checked;
        cb.onchange();
      };
      row.ondblclick = (e) => {
        e.stopPropagation();
        this.openEditor(f.path);
      };

      row.append(spacer, cb, name, meta);
      container.appendChild(row);
    });
  },

  renderFiles() {
    const q = document.getElementById("filter").value.toLowerCase().trim();
    const list = document.getElementById("fileList");
    list.innerHTML = "";

    const filtered = q
      ? this.files.filter((f) => f.path.toLowerCase().includes(q))
      : this.files;

    const tree = this.buildFileTree(filtered);
    this.renderTreeNode(tree, list, Boolean(q));
    this.updateStats();
  },

  renderChips() {
    const box = document.getElementById("selectedChips");
    box.innerHTML = "";
    this.selected.forEach((spec, path) => {
      const chip = document.createElement("div");
      chip.className = "chip";
      const lbl = document.createElement("span");
      lbl.textContent = path;

      const modeBtn = document.createElement("button");
      modeBtn.className = "btn ghost";
      modeBtn.style.padding = "2px 8px";
      modeBtn.style.fontSize = "11px";
      modeBtn.textContent = `${spec.mode} ▾`;
      modeBtn.onclick = () => {
        this.openChoiceModal({
          title: `Context Mode for ${path}`,
          description: "Choose how much of this file to include in the AI prompt:",
          options: [
            {
              label: "Full File",
              hint: `~${spec.tokens} tokens`,
              onSelect: () => {
                spec.mode = "full";
                this.renderChips();
                this.updateStats();
                this.toast(`${path} set to full mode`);
              },
            },
            {
              label: "Outline Only (Save ~80% Tokens)",
              hint: `~${Math.round(spec.tokens * 0.2)} tokens`,
              onSelect: () => {
                spec.mode = "outline";
                this.renderChips();
                this.updateStats();
                this.toast(`${path} set to outline mode`);
              },
            },
            {
              label: "Specific Line Range",
              hint: "Choose start & end lines",
              onSelect: () => {
                spec.mode = "range";
                this.renderChips();
                this.updateStats();
              },
            },
            {
              label: "Remove File from Selection",
              hint: "Exclude",
              onSelect: () => {
                this.selected.delete(path);
                this.renderFiles();
                this.renderChips();
              },
            },
          ],
        });
      };
      chip.append(lbl, modeBtn);

      if (spec.mode === "range") {
        const sIn = document.createElement("input");
        sIn.className = "rng";
        sIn.placeholder = "start";
        sIn.value = spec.start;
        sIn.oninput = () => (spec.start = parseInt(sIn.value) || "");
        const eIn = document.createElement("input");
        eIn.className = "rng";
        eIn.placeholder = "end";
        eIn.value = spec.end;
        eIn.oninput = () => (spec.end = parseInt(eIn.value) || "");
        chip.append(sIn, eIn);
      }
      box.appendChild(chip);
    });
  },

  updateStats() {
    document.getElementById("fileStats").textContent = `${this.selected.size} / ${this.files.length} files`;
    let total = 0;
    this.selected.forEach((s) => {
      total += s.mode === "outline" ? Math.round(s.tokens * 0.2) : s.tokens;
    });
    document.getElementById("selectedTokens").textContent = `~${total.toLocaleString()} tokens`;
  },

  toggleAll(on) {
    const q = document.getElementById("filter").value.toLowerCase();
    this.files.forEach((f) => {
      if (!q || f.path.toLowerCase().includes(q)) {
        if (on) {
          const mode = f.est_tokens > 4000 ? "outline" : "full";
          this.selected.set(f.path, { path: f.path, mode, start: "", end: "", tokens: f.est_tokens });
        } else {
          this.selected.delete(f.path);
        }
      }
    });
    this.renderFiles();
    this.renderChips();
  },

  collectAnswers() {
    const answers = [];
    this.pendingQuestions.forEach((q, idx) => {
      const checked = document.querySelector(`input[name="qa_${idx}"]:checked`);
      const custom = document.getElementById(`qa_custom_${idx}`).value.trim();
      const ans = custom || (checked ? checked.value : "");
      if (ans) answers.push({ question: q.question, answer: ans });
    });
    return answers;
  },

  renderPlan(planItems) {
    const panel = document.getElementById("planPanel");
    const box = document.getElementById("planOut");
    const meta = document.getElementById("planMeta");

    if (planItems && planItems.length) {
      this.planTasks = planItems;
    }

    if (!this.planTasks.length) {
      panel.classList.add("hidden");
      panel.open = false;
      box.innerHTML = "";
      return;
    }

    panel.classList.remove("hidden");
    box.innerHTML = "";
    let totalCount = 0;
    let doneCount = 0;

    this.planTasks.forEach((item) => {
      totalCount += 1;
      if (item.done) doneCount += 1;

      const wrap = document.createElement("div");
      wrap.className = "plan-item";

      const mainRow = document.createElement("label");
      mainRow.className = "plan-main";
      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.style.width = "auto";
      cb.checked = Boolean(item.done);
      const txt = document.createElement("span");
      txt.textContent = item.text;
      if (item.done) txt.className = "plan-done";
      cb.onchange = () => {
        item.done = cb.checked;
        txt.className = cb.checked ? "plan-done" : "";
      };
      mainRow.append(cb, txt);
      wrap.appendChild(mainRow);

      if (item.subtasks && item.subtasks.length) {
        const subBox = document.createElement("div");
        subBox.className = "plan-sublist";
        item.subtasks.forEach((sub) => {
          totalCount += 1;
          if (sub.done) doneCount += 1;
          const subRow = document.createElement("label");
          subRow.className = "plan-sub";
          const scb = document.createElement("input");
          scb.type = "checkbox";
          scb.style.width = "auto";
          scb.checked = Boolean(sub.done);
          const stxt = document.createElement("span");
          stxt.textContent = sub.text;
          if (sub.done) stxt.className = "plan-done";
          scb.onchange = () => {
            sub.done = scb.checked;
            stxt.className = scb.checked ? "plan-done" : "";
          };
          subRow.append(scb, stxt);
          subBox.appendChild(subRow);
        });
        wrap.appendChild(subBox);
      }
      box.appendChild(wrap);
    });

    meta.textContent = `${doneCount}/${totalCount} completed (click to expand)`;
  },

  async buildPrompt(isAutoNext = false) {
    const task = document.getElementById("task").value.trim();
    if (!task) return this.toast("Describe your goal first.");

    this.goalFinished = false;

    if (
      !isAutoNext &&
      this.goalStep === 1 &&
      this.selected.size === 0 &&
      document.getElementById("autoSelectSmart").checked
    ) {
      await this.smartSelect();
    }

    const include_tree = document.getElementById("includeTree").checked;
    const chunk_size = parseInt(document.getElementById("chunkSize").value) || 120000;
    const files = Array.from(this.selected.values());
    const answers = this.collectAnswers();

    const res = await fetch("/api/build_prompt", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        task,
        files,
        include_tree,
        chunk_size,
        goal_step: this.goalStep,
        answers,
        applied_log: this.appliedLog,
      }),
    });
    const data = await res.json();
    document.getElementById("generatedPrompt").value = data.full_prompt;
    document.getElementById("promptMeta").textContent =
      `${data.chars.toLocaleString()} chars (~${data.est_tokens.toLocaleString()} tokens)`;

    const btns = document.getElementById("copyButtons");
    btns.innerHTML = "";
    data.parts.forEach((part, idx) => {
      const b = document.createElement("button");
      b.className = "btn success";
      const label = data.parts.length === 1 ? "Copy Prompt" : `Copy Part ${idx + 1}/${data.parts.length}`;
      b.textContent = label;
      b.onclick = async () => {
        await navigator.clipboard.writeText(part);
        this.toast(`${label} copied!`);
        if (document.getElementById("autoUnselect").checked) {
          this.selected.clear();
          this.renderFiles();
          this.renderChips();
        }
      };
      btns.appendChild(b);
    });

    const triggerAiHandoffPopup = (copiedOk) => {
      const firstLabel = data.parts.length === 1 ? "Prompt" : `Part 1/${data.parts.length}`;
      this.showPopup({
        type: "red",
        title: copiedOk
          ? `${firstLabel} Copied — Go Paste in AI & Copy Reply`
          : "Prompt Ready — Copy & Paste in AI Chat",
        message: "1) Paste the prompt into your AI chat. 2) Copy the AI's response. 3) Click Done below to auto-apply and advance.",
        actions: [
          {
            label: "Copy Prompt Again",
            cls: "ghost",
            onClick: async () => {
              await navigator.clipboard.writeText(data.parts[0]);
              triggerAiHandoffPopup(true);
            },
          },
          {
            label: "Done (Paste & Run Next Step)",
            cls: "danger",
            onClick: async () => {
              const aiBox = document.getElementById("aiResponse");
              this.setStage("paste");
              try {
                const clipText = await navigator.clipboard.readText();
                if (clipText && clipText.trim() && clipText.trim() !== data.parts[0].trim()) {
                  aiBox.value = clipText;
                  await this.runOps(true);
                  return;
                }
              } catch (e) {
                // Fallback if clipboard read permission is blocked
              }
              if (aiBox.value.trim()) {
                await this.runOps(true);
              } else {
                aiBox.focus();
                this.showPopup({
                  type: "red",
                  title: "Paste AI Response Below",
                  message: "Press Ctrl+V inside the response box (or copy the AI reply first and click Done again).",
                });
              }
            },
          },
        ],
      });
    };

    if (data.parts && data.parts.length > 0) {
      try {
        await navigator.clipboard.writeText(data.parts[0]);
        if (document.getElementById("autoUnselect").checked) {
          this.selected.clear();
          this.renderFiles();
          this.renderChips();
        }
        triggerAiHandoffPopup(true);
      } catch (e) {
        triggerAiHandoffPopup(false);
      }
    }

    this.setGoalBadge("WAITING REPLY", "active");
    this.setStage("paste");
  },

  renderQuestions(questions) {
    this.pendingQuestions = questions || [];
    const box = document.getElementById("questionsOut");
    box.innerHTML = "";
    if (!this.pendingQuestions.length) return;

    this.pendingQuestions.forEach((q, idx) => {
      const card = document.createElement("div");
      card.className = "qa-card";
      const title = document.createElement("div");
      title.className = "qa-title";
      title.textContent = q.question;
      card.appendChild(title);

      (q.options || []).forEach((opt) => {
        const lbl = document.createElement("label");
        lbl.className = "qa-opt";
        const r = document.createElement("input");
        r.type = "radio";
        r.name = `qa_${idx}`;
        r.value = opt;
        r.onchange = () => {
          if (this.pendingQuestions.length === 1) {
            this.submitAnswersAndAdvance();
          }
        };
        lbl.append(r, document.createTextNode(opt));
        card.appendChild(lbl);
      });

      const custom = document.createElement("input");
      custom.id = `qa_custom_${idx}`;
      custom.placeholder = "Or type a custom answer and press Enter...";
      custom.onkeydown = (e) => {
        if (e.key === "Enter") {
          e.preventDefault();
          this.submitAnswersAndAdvance();
        }
      };
      card.appendChild(custom);
      box.appendChild(card);
    });

    const submitRow = document.createElement("div");
    submitRow.className = "row";
    const btn = document.createElement("button");
    btn.className = "btn primary";
    btn.textContent = "Send Answers & Copy Next Prompt →";
    btn.onclick = () => this.submitAnswersAndAdvance();
    submitRow.appendChild(btn);
    box.appendChild(submitRow);
  },

  async submitAnswersAndAdvance() {
    this.goalStep += 1;
    await this.buildPrompt(true);
    document.getElementById("aiResponse").value = "";
    this.renderQuestions([]);
    this.toast(`Step ${this.goalStep} prompt with answers copied!`);
  },

  async runOps(apply) {
    const text = document.getElementById("aiResponse").value;
    let fallback_path = document.getElementById("fallbackFile").value.trim();
    if (!fallback_path && this.selected.size === 1) {
      fallback_path = Array.from(this.selected.keys())[0];
    }

    const res = await fetch("/api/apply", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text, apply, fallback_path }),
    });
    const data = await res.json();

    if (data.plan && data.plan.length) {
      this.renderPlan(data.plan);
    }

    const hasQuestions = (data.questions || []).length > 0;
    const hasNeedFiles = (data.need_files || []).length > 0;

    this.renderQuestions(data.questions || []);

    const out = document.getElementById("diffOut");
    out.innerHTML = "";
    const results = data.results || [];
    document.getElementById("applyMeta").textContent =
      `${results.length} edit(s) · ${(data.need_files || []).length} file req(s) · ${(data.questions || []).length} question(s)`;

    let appliedCount = 0;
    let errorCount = 0;
    results.forEach((r) => {
      const isApplied = apply && r.status === "applied";
      const card = document.createElement("details");
      card.className = "diff-file";
      card.open = !isApplied;

      const hdr = document.createElement("summary");
      hdr.className = `diff-header ${r.status}`;
      hdr.style.cursor = "pointer";
      hdr.textContent = `${isApplied ? "▸" : "▾"} [${r.status.toUpperCase()}] ${r.path}`;
      card.ontoggle = () => {
        hdr.textContent = `${card.open ? "▾" : "▸"} [${r.status.toUpperCase()}] ${r.path}`;
      };
      card.appendChild(hdr);

      const body = document.createElement("div");
      body.className = "diff-body";
      if (r.message) {
        const line = document.createElement("div");
        line.className = "dline del";
        line.textContent = r.message;
        body.appendChild(line);
      } else if (r.diff_lines && r.diff_lines.length) {
        r.diff_lines.forEach((dl) => {
          const line = document.createElement("div");
          line.className = `dline ${dl.kind}`;
          line.textContent = dl.text;
          body.appendChild(line);
        });
      } else {
        const line = document.createElement("div");
        line.className = "dline meta";
        line.textContent = "(no text changes)";
        body.appendChild(line);
      }
      card.appendChild(body);
      out.appendChild(card);

      if (isApplied) {
        appliedCount += 1;
        this.appliedLog.push(`Step ${this.goalStep}: updated ${r.path}`);
      } else if (r.status === "error") {
        errorCount += 1;
      }
    });

    const applyBtn = document.getElementById("applyBtn");
    if (applyBtn) {
      const autoOn = document.getElementById("autoProcessPaste").checked;
      applyBtn.classList.toggle("hidden", autoOn && appliedCount > 0 && errorCount === 0);
    }

    if (apply && appliedCount > 0) {
      await this.loadFiles();
    }

    // Handle AI-requested files automatically
    if (hasNeedFiles) {
      data.need_files.forEach((nf) => {
        const match = this.files.find((f) => f.path === nf.path);
        this.selected.set(nf.path, {
          path: nf.path,
          mode: nf.mode || "full",
          start: nf.start || "",
          end: nf.end || "",
          tokens: match ? match.est_tokens : 500,
        });
      });
      this.renderFiles();
      this.renderChips();

      if (!hasQuestions) {
        this.goalStep += 1;
        await this.buildPrompt(true);
        document.getElementById("aiResponse").value = "";
        this.setGoalBadge("WAITING NEXT", "active");
        this.toast(`Step ${this.goalStep}: copied ${data.need_files.length} requested file(s)!`);
        return;
      }
    }

    // Automatically advance to next step when AI indicates APPLIED_NEXT
    if (apply && data.status_flag === "APPLIED_NEXT" && !hasQuestions && errorCount === 0) {
      this.goalStep += 1;
      await this.buildPrompt(true);
      document.getElementById("aiResponse").value = "";
      this.setGoalBadge("WAITING NEXT", "active");
      this.toast(`Applied ${appliedCount} file(s) & copied Step ${this.goalStep} prompt!`);
      return;
    }

    if (data.status_flag === "DONE") {
      this.goalFinished = true;
      this.selected.clear();
      this.renderFiles();
      this.renderChips();
      this.setGoalBadge("DONE", "done");
      this.setStage("paste");
      this.showPopup({
        type: "success",
        title: "Goal Completed!",
        message: appliedCount > 0
          ? `Successfully applied ${appliedCount} file(s). Expand any file below to review its diff.`
          : "All steps for this goal are complete.",
        actions: [
          {
            label: "Start New Goal",
            cls: "success",
            onClick: () => this.resetGoal(),
          },
        ],
      });
    } else if (hasQuestions || data.status_flag === "NEED_MORE" || data.status_flag === "APPLIED_NEXT") {
      this.setGoalBadge("WAITING INPUT", "active");
      if (hasQuestions) {
        this.showPopup({
          type: "info",
          title: "AI Needs Your Input",
          message: "Choose an option below (or type a custom answer) to generate and copy the next prompt.",
        });
      }
    } else if (apply && appliedCount > 0) {
      this.showPopup({
        type: "success",
        title: `Applied ${appliedCount} File(s)`,
        message: "Changes saved to disk. Expand any file below to inspect the diff.",
      });
    } else if (errorCount > 0) {
      this.showPopup({
        type: "red",
        title: "Patch Error",
        message: "One or more edits could not be applied. Check the details below.",
      });
    }
  },

  // Code Editor Modal
  async openEditor(relPath) {
    const res = await fetch(`/api/file?path=${encodeURIComponent(relPath)}`);
    const data = await res.json();
    if (!res.ok) return this.toast(data.error || "Failed to open file");

    this.editingPath = relPath;
    document.getElementById("editorTitle").textContent = relPath;
    const ext = relPath.includes(".") ? relPath.split(".").pop().toUpperCase() : "TEXT";
    document.getElementById("editorLangBadge").textContent = ext;

    const area = document.getElementById("editorCode");
    area.value = data.content;
    this.syncEditorGutter();
    document.getElementById("editorModal").classList.remove("hidden");
    area.focus();
  },

  closeEditor() {
    document.getElementById("editorModal").classList.add("hidden");
    this.editingPath = "";
  },

  syncEditorGutter() {
    const area = document.getElementById("editorCode");
    const gutter = document.getElementById("editorLines");
    const lineCount = (area.value.match(/\n/g) || []).length + 1;
    const nums = [];
    for (let i = 1; i <= lineCount; i++) nums.push(i);
    gutter.textContent = nums.join("\n");
  },

  syncEditorScroll() {
    const area = document.getElementById("editorCode");
    const gutter = document.getElementById("editorLines");
    gutter.scrollTop = area.scrollTop;
  },

  prettifyEditor() {
    const area = document.getElementById("editorCode");
    const ext = this.editingPath.split(".").pop().toLowerCase();
    try {
      if (ext === "json") {
        area.value = JSON.stringify(JSON.parse(area.value), null, 2);
        this.syncEditorGutter();
        return this.toast("Formatted JSON");
      }
      // Clean trailing spaces, normalize tabs to 2/4 spaces, and ensure single trailing newline
      const indent = ext === "py" ? "    " : "  ";
      const cleaned = area.value
        .replace(/\r\n/g, "\n")
        .split("\n")
        .map((line) => line.replace(/\t/g, indent).replace(/[ \t]+$/, ""))
        .join("\n")
        .replace(/\n{3,}/g, "\n\n")
        .trimEnd() + "\n";
      area.value = cleaned;
      this.syncEditorGutter();
      this.toast("Prettified whitespace & indentation");
    } catch (e) {
      this.toast(`Format error: ${e.message}`);
    }
  },

  async saveEditor() {
    if (!this.editingPath) return;
    const content = document.getElementById("editorCode").value;
    const res = await fetch("/api/file", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path: this.editingPath, content }),
    });
    const data = await res.json();
    if (!res.ok) return this.toast(data.error || "Save failed");
    await this.loadFiles();
    this.toast(`Saved ${this.editingPath}`);
  },

  init() {
    // Clear browser-restored form inputs on page reload so Smart Select never auto-picks stale goals
    document.getElementById("task").value = "";
    document.getElementById("aiResponse").value = "";
    document.getElementById("generatedPrompt").value = "";
    document.getElementById("fallbackFile").value = "";
    this.setStage("goal");

    const autoPasteChk = document.getElementById("autoProcessPaste");
    const applyBtn = document.getElementById("applyBtn");
    const syncApplyBtnVisibility = () => {
      if (applyBtn) applyBtn.classList.toggle("hidden", autoPasteChk.checked);
    };
    syncApplyBtnVisibility();
    autoPasteChk.addEventListener("change", syncApplyBtnVisibility);

    const aiBox = document.getElementById("aiResponse");
    aiBox.addEventListener("paste", () => {
      if (!autoPasteChk.checked) return;
      setTimeout(() => {
        if (aiBox.value.trim()) this.runOps(true);
      }, 60);
    });

    const taskBox = document.getElementById("task");
    let smartTimer = null;
    taskBox.addEventListener("input", () => {
      if (this.goalFinished) this.goalFinished = false;
      if (!document.getElementById("autoSelectSmart").checked) return;
      clearTimeout(smartTimer);
      smartTimer = setTimeout(() => {
        if (
          this.stage === "goal" &&
          !this.goalFinished &&
          this.goalStep === 1 &&
          taskBox.value.trim().length >= 8 &&
          this.selected.size === 0
        ) {
          this.smartSelect();
        }
      }, 650);
    });

    const editorArea = document.getElementById("editorCode");
    editorArea.addEventListener("keydown", (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "s") {
        e.preventDefault();
        this.saveEditor();
      } else if (e.key === "Tab") {
        e.preventDefault();
        const start = editorArea.selectionStart;
        const end = editorArea.selectionEnd;
        const indent = this.editingPath.endsWith(".py") ? "    " : "  ";
        editorArea.value = editorArea.value.substring(0, start) + indent + editorArea.value.substring(end);
        editorArea.selectionStart = editorArea.selectionEnd = start + indent.length;
        this.syncEditorGutter();
      }
    });
  },
};

App.init();
App.loadFiles();

const App = {
  files: [],
  selected: new Map(), // path -> { path, mode, start, end, tokens }
  expandedDirs: new Set(),
  browseParent: "",
  goalStep: 1,
  goalFinished: false,
  stage: "goal", // "goal" | "paste"
  appliedLog: [],
  pendingQuestions: [],
  planTasks: [],
  editingPath: "",

  showPopup({ type = "info", title = "", message = "", actions = [] }) {
    const box = document.getElementById("inlinePopup");
    const iconEl = document.getElementById("inlinePopupIcon");
    const titleEl = document.getElementById("inlinePopupTitle");
    const msgEl = document.getElementById("inlinePopupMsg");
    const actEl = document.getElementById("inlinePopupActions");
    if (!box) return;

    box.className = `inline-popup ${type}`;
    const icons = { info: "ℹ️", success: "✅", red: "🚨" };
    iconEl.textContent = icons[type] || "ℹ️";
    titleEl.textContent = title || (type === "red" ? "Action Required: Paste in AI Chat" : "Status");
    msgEl.textContent = message;

    actEl.innerHTML = "";
    actions.forEach((act) => {
      const b = document.createElement("button");
      b.className = `btn ${act.cls || "primary"}`;
      b.textContent = act.label;
      b.onclick = act.onClick;
      actEl.appendChild(b);
    });
  },

  toast(msg, type = "info") {
    this.showPopup({
      type,
      title: type === "success" ? "Completed" : "Status Update",
      message: msg,
    });
  },

  openOptionsModal() {
    document.getElementById("optionsModal").classList.remove("hidden");
  },

  closeOptionsModal() {
    document.getElementById("optionsModal").classList.add("hidden");
  },

  openChoiceModal({ title, description = "", options = [] }) {
    document.getElementById("choiceModalTitle").textContent = title;
    document.getElementById("choiceModalDesc").textContent = description;
    const body = document.getElementById("choiceModalBody");
    body.innerHTML = "";

    options.forEach((opt) => {
      const btn = document.createElement("button");
      btn.className = "choice-option-btn";
      const lbl = document.createElement("span");
      lbl.textContent = opt.label;
      const hint = document.createElement("span");
      hint.className = "muted";
      hint.textContent = opt.hint || "";
      btn.append(lbl, hint);
      btn.onclick = () => {
        this.closeChoiceModal();
        if (opt.onSelect) opt.onSelect();
      };
      body.appendChild(btn);
    });

    document.getElementById("choiceModal").classList.remove("hidden");
  },

  closeChoiceModal() {
    document.getElementById("choiceModal").classList.add("hidden");
  },

  setGoalBadge(stateText, cls = "") {
    const b = document.getElementById("goalBadge");
    b.textContent = `Goal: Step ${this.goalStep} (${stateText})`;
    b.className = `badge goal ${cls}`;
  },

  setStage(stage) {
    this.stage = stage;
    const promptCard = document.getElementById("stagePromptCard");
    const pasteCard = document.getElementById("stagePasteCard");
    const switchBtn = document.getElementById("switchToPasteBtn");

    if (stage === "goal") {
      promptCard.classList.remove("hidden");
      pasteCard.classList.add("hidden");
      if (this.goalStep > 1 || document.getElementById("generatedPrompt").value.trim()) {
        switchBtn.classList.remove("hidden");
      } else {
        switchBtn.classList.add("hidden");
      }
    } else {
      promptCard.classList.add("hidden");
      pasteCard.classList.remove("hidden");
      const pasteArea = document.getElementById("pasteInputArea");
      const doneActions = document.getElementById("doneActions");
      if (this.goalFinished) {
        pasteArea.classList.add("hidden");
        doneActions.classList.remove("hidden");
      } else {
        pasteArea.classList.remove("hidden");
        doneActions.classList.add("hidden");
      }
    }
  },

  togglePromptPreview() {
    document.getElementById("promptPreviewWrap").classList.toggle("hidden");
  },

  resetGoal() {
    this.goalStep = 1;
    this.goalFinished = false;
    this.appliedLog = [];
    this.pendingQuestions = [];
    this.planTasks = [];
    this.selected.clear();

    document.getElementById("task").value = "";
    document.getElementById("generatedPrompt").value = "";
    document.getElementById("promptMeta").textContent = "";
    document.getElementById("copyButtons").innerHTML = "";
    document.getElementById("questionsOut").innerHTML = "";
    document.getElementById("diffOut").innerHTML = "";
    document.getElementById("aiResponse").value = "";
    document.getElementById("applyMeta").textContent = "";
    document.getElementById("promptPreviewWrap").classList.add("hidden");

    const autoPasteChk = document.getElementById("autoProcessPaste");
    const applyBtn = document.getElementById("applyBtn");
    if (applyBtn && autoPasteChk) {
      applyBtn.classList.toggle("hidden", autoPasteChk.checked);
    }

    this.renderPlan([]);
    this.renderFiles();
    this.renderChips();
    this.setGoalBadge("IDLE");
    this.setStage("goal");
    this.showPopup({
      type: "info",
      title: "Ready for a New Goal",
      message: "Describe what you want to build or fix, or double-click any file on the left to inspect/edit.",
    });
  },

  async loadFiles() {
    const res = await fetch("/api/files");
    const data = await res.json();
    this.files = data.files || [];
    this.renderFiles();
  },

  async setProject(customPath = null) {
    const path = customPath !== null ? customPath : document.getElementById("projPath").value;
    const res = await fetch("/api/project", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path }),
    });
    const data = await res.json();
    if (!res.ok) return this.toast(data.error);
    document.getElementById("projPath").value = data.root;
    this.expandedDirs.clear();
    this.resetGoal();
    await this.loadFiles();
    this.toast("Project loaded");
  },

  async smartSelect() {
    if (this.goalFinished) return;
    const task = document.getElementById("task").value.trim();
    if (!task) return this.toast("Enter a task first so Smart Select can match files.");
    const res = await fetch("/api/smart_select", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ task }),
    });
    const data = await res.json();
    this.selected.clear();
    (data.selected || []).forEach((s) => {
      this.selected.set(s.path, { path: s.path, mode: s.mode, start: "", end: "", tokens: s.tokens || 500 });
    });
    this.renderFiles();
    this.renderChips();
    this.toast(`Smart Select picked ${this.selected.size} file(s)`);
  },

  async openBrowser() {
    document.getElementById("browserModal").classList.remove("hidden");
    await this.browseTo(document.getElementById("projPath").value);
  },

  closeBrowser() {
    document.getElementById("browserModal").classList.add("hidden");
  },

  async browseTo(path) {
    const res = await fetch(`/api/browse?path=${encodeURIComponent(path || "")}`);
    const data = await res.json();
    document.getElementById("browsePath").value = data.current;
    this.browseParent = data.parent || "";
    document.getElementById("upBtn").disabled = !this.browseParent;

    const drives = document.getElementById("driveBar");
    drives.innerHTML = "";
    (data.drives || []).forEach((d) => {
      const b = document.createElement("button");
      b.className = "btn ghost";
      b.textContent = d;
      b.onclick = () => this.browseTo(d);
      drives.appendChild(b);
    });

    const list = document.getElementById("dirList");
    list.innerHTML = "";
    (data.dirs || []).forEach((d) => {
      const row = document.createElement("div");
      row.className = "fitem";
      row.textContent = "📁 " + d.name;
      row.onclick = () => this.browseTo(d.path);
      list.appendChild(row);
    });
  },

  browseUp() {
    if (this.browseParent) this.browseTo(this.browseParent);
  },

  async selectBrowsed() {
    const chosen = document.getElementById("browsePath").value;
    this.closeBrowser();
    await this.setProject(chosen);
  },

  buildFileTree(files) {
    const root = { name: "", path: "", folders: new Map(), files: [] };
    files.forEach((f) => {
      const parts = f.path.split("/");
      let node = root;
      for (let i = 0; i < parts.length - 1; i++) {
        const seg = parts[i];
        const nextPath = node.path ? `${node.path}/${seg}` : seg;
        if (!node.folders.has(seg)) {
          node.folders.set(seg, { name: seg, path: nextPath, folders: new Map(), files: [] });
        }
        node = node.folders.get(seg);
      }
      node.files.push({ ...f, name: parts[parts.length - 1] });
    });
    return root;
  },

  collectFolderFiles(node, acc = []) {
    node.files.forEach((f) => acc.push(f));
    node.folders.forEach((sub) => this.collectFolderFiles(sub, acc));
    return acc;
  },

  renderTreeNode(node, container, isFilterActive) {
    const sortedFolders = Array.from(node.folders.values()).sort((a, b) => a.name.localeCompare(b.name));
    sortedFolders.forEach((folder) => {
      const descendantFiles = this.collectFolderFiles(folder, []);
      if (!descendantFiles.length) return;

      const wrap = document.createElement("div");
      wrap.className = "tree-folder";

      const row = document.createElement("div");
      row.className = "tree-row";

      const isCollapsed = !isFilterActive && this.collapsedDirs.has(folder.path);
      const caret = document.createElement("span");
      caret.className = "tree-caret";
      caret.textContent = isCollapsed ? "▸" : "▾";

      const cb = document.createElement("input");
      cb.type = "checkbox";
      const selectedCount = descendantFiles.filter((f) => this.selected.has(f.path)).length;
      cb.checked = selectedCount > 0 && selectedCount === descendantFiles.length;
      cb.indeterminate = selectedCount > 0 && selectedCount < descendantFiles.length;
      cb.onclick = (e) => e.stopPropagation();
      cb.onchange = () => {
        descendantFiles.forEach((f) => {
          if (cb.checked) {
            const mode = f.est_tokens > 4000 ? "outline" : "full";
            this.selected.set(f.path, { path: f.path, mode, start: "", end: "", tokens: f.est_tokens });
          } else {
            this.selected.delete(f.path);
          }
        });
        this.renderFiles();
        this.renderChips();
      };

      const lbl = document.createElement("span");
      lbl.className = "tree-folder-lbl";
      lbl.textContent = `📁 ${folder.name}`;

      row.onclick = () => {
        if (this.collapsedDirs.has(folder.path)) {
          this.collapsedDirs.delete(folder.path);
        } else {
          this.collapsedDirs.add(folder.path);
        }
        this.renderFiles();
      };

      row.append(caret, cb, lbl);
      wrap.appendChild(row);

      const childrenBox = document.createElement("div");
      childrenBox.className = `tree-children${isCollapsed ? " collapsed" : ""}`;
      this.renderTreeNode(folder, childrenBox, isFilterActive);
      wrap.appendChild(childrenBox);
      container.appendChild(wrap);
    });

    const sortedFiles = [...node.files].sort((a, b) => a.name.localeCompare(b.name));
    sortedFiles.forEach((f) => {
      const row = document.createElement("div");
      row.className = "tree-row";
      row.title = "Double-click to view or edit file";

      const spacer = document.createElement("span");
      spacer.className = "tree-caret";
      spacer.textContent = "";

      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.checked = this.selected.has(f.path);
      cb.onclick = (e) => e.stopPropagation();
      cb.onchange = () => {
        if (cb.checked) {
          const defaultMode = f.est_tokens > 4000 ? "outline" : "full";
          this.selected.set(f.path, { path: f.path, mode: defaultMode, start: "", end: "", tokens: f.est_tokens });
        } else {
          this.selected.delete(f.path);
        }
        this.renderFiles();
        this.renderChips();
      };

      const name = document.createElement("span");
      name.className = "tree-file-lbl";
      name.textContent = f.name;

      const meta = document.createElement("span");
      meta.className = "fmeta";
      meta.textContent = `~${f.est_tokens}t`;

      row.onclick = () => {
        cb.checked = !cb.checked;
        cb.onchange();
      };
      row.ondblclick = (e) => {
        e.stopPropagation();
        this.openEditor(f.path);
      };

      row.append(spacer, cb, name, meta);
      container.appendChild(row);
    });
  },

  renderFiles() {
    const q = document.getElementById("filter").value.toLowerCase().trim();
    const list = document.getElementById("fileList");
    list.innerHTML = "";

    const filtered = q
      ? this.files.filter((f) => f.path.toLowerCase().includes(q))
      : this.files;

    const tree = this.buildFileTree(filtered);
    this.renderTreeNode(tree, list, Boolean(q));
    this.updateStats();
  },

  renderChips() {
    const box = document.getElementById("selectedChips");
    box.innerHTML = "";
    this.selected.forEach((spec, path) => {
      const chip = document.createElement("div");
      chip.className = "chip";
      const lbl = document.createElement("span");
      lbl.textContent = path;

      const modeBtn = document.createElement("button");
      modeBtn.className = "btn ghost";
      modeBtn.style.padding = "2px 8px";
      modeBtn.style.fontSize = "11px";
      modeBtn.textContent = `${spec.mode} ▾`;
      modeBtn.onclick = () => {
        this.openChoiceModal({
          title: `Context Mode for ${path}`,
          description: "Choose how much of this file to include in the AI prompt:",
          options: [
            {
              label: "Full File",
              hint: `~${spec.tokens} tokens`,
              onSelect: () => {
                spec.mode = "full";
                this.renderChips();
                this.updateStats();
                this.toast(`${path} set to full mode`);
              },
            },
            {
              label: "Outline Only (Save ~80% Tokens)",
              hint: `~${Math.round(spec.tokens * 0.2)} tokens`,
              onSelect: () => {
                spec.mode = "outline";
                this.renderChips();
                this.updateStats();
                this.toast(`${path} set to outline mode`);
              },
            },
            {
              label: "Specific Line Range",
              hint: "Choose start & end lines",
              onSelect: () => {
                spec.mode = "range";
                this.renderChips();
                this.updateStats();
              },
            },
            {
              label: "Remove File from Selection",
              hint: "Exclude",
              onSelect: () => {
                this.selected.delete(path);
                this.renderFiles();
                this.renderChips();
              },
            },
          ],
        });
      };
      chip.append(lbl, modeBtn);

      if (spec.mode === "range") {
        const sIn = document.createElement("input");
        sIn.className = "rng";
        sIn.placeholder = "start";
        sIn.value = spec.start;
        sIn.oninput = () => (spec.start = parseInt(sIn.value) || "");
        const eIn = document.createElement("input");
        eIn.className = "rng";
        eIn.placeholder = "end";
        eIn.value = spec.end;
        eIn.oninput = () => (spec.end = parseInt(eIn.value) || "");
        chip.append(sIn, eIn);
      }
      box.appendChild(chip);
    });
  },

  updateStats() {
    document.getElementById("fileStats").textContent = `${this.selected.size} / ${this.files.length} files`;
    let total = 0;
    this.selected.forEach((s) => {
      total += s.mode === "outline" ? Math.round(s.tokens * 0.2) : s.tokens;
    });
    document.getElementById("selectedTokens").textContent = `~${total.toLocaleString()} tokens`;
  },

  toggleAll(on) {
    const q = document.getElementById("filter").value.toLowerCase();
    this.files.forEach((f) => {
      if (!q || f.path.toLowerCase().includes(q)) {
        if (on) {
          const mode = f.est_tokens > 4000 ? "outline" : "full";
          this.selected.set(f.path, { path: f.path, mode, start: "", end: "", tokens: f.est_tokens });
        } else {
          this.selected.delete(f.path);
        }
      }
    });
    this.renderFiles();
    this.renderChips();
  },

  collectAnswers() {
    const answers = [];
    this.pendingQuestions.forEach((q, idx) => {
      const checked = document.querySelector(`input[name="qa_${idx}"]:checked`);
      const custom = document.getElementById(`qa_custom_${idx}`).value.trim();
      const ans = custom || (checked ? checked.value : "");
      if (ans) answers.push({ question: q.question, answer: ans });
    });
    return answers;
  },

  renderPlan(planItems) {
    const panel = document.getElementById("planPanel");
    const box = document.getElementById("planOut");
    const meta = document.getElementById("planMeta");

    if (planItems && planItems.length) {
      this.planTasks = planItems;
    }

    if (!this.planTasks.length) {
      panel.classList.add("hidden");
      panel.open = false;
      box.innerHTML = "";
      return;
    }

    panel.classList.remove("hidden");
    box.innerHTML = "";
    let totalCount = 0;
    let doneCount = 0;

    this.planTasks.forEach((item) => {
      totalCount += 1;
      if (item.done) doneCount += 1;

      const wrap = document.createElement("div");
      wrap.className = "plan-item";

      const mainRow = document.createElement("label");
      mainRow.className = "plan-main";
      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.style.width = "auto";
      cb.checked = Boolean(item.done);
      const txt = document.createElement("span");
      txt.textContent = item.text;
      if (item.done) txt.className = "plan-done";
      cb.onchange = () => {
        item.done = cb.checked;
        txt.className = cb.checked ? "plan-done" : "";
      };
      mainRow.append(cb, txt);
      wrap.appendChild(mainRow);

      if (item.subtasks && item.subtasks.length) {
        const subBox = document.createElement("div");
        subBox.className = "plan-sublist";
        item.subtasks.forEach((sub) => {
          totalCount += 1;
          if (sub.done) doneCount += 1;
          const subRow = document.createElement("label");
          subRow.className = "plan-sub";
          const scb = document.createElement("input");
          scb.type = "checkbox";
          scb.style.width = "auto";
          scb.checked = Boolean(sub.done);
          const stxt = document.createElement("span");
          stxt.textContent = sub.text;
          if (sub.done) stxt.className = "plan-done";
          scb.onchange = () => {
            sub.done = scb.checked;
            stxt.className = scb.checked ? "plan-done" : "";
          };
          subRow.append(scb, stxt);
          subBox.appendChild(subRow);
        });
        wrap.appendChild(subBox);
      }
      box.appendChild(wrap);
    });

    meta.textContent = `${doneCount}/${totalCount} completed (click to expand)`;
  },

  async buildPrompt(isAutoNext = false) {
    const task = document.getElementById("task").value.trim();
    if (!task) return this.toast("Describe your goal first.");

    this.goalFinished = false;

    if (
      !isAutoNext &&
      this.goalStep === 1 &&
      this.selected.size === 0 &&
      document.getElementById("autoSelectSmart").checked
    ) {
      await this.smartSelect();
    }

    const include_tree = document.getElementById("includeTree").checked;
    const chunk_size = parseInt(document.getElementById("chunkSize").value) || 120000;
    const files = Array.from(this.selected.values());
    const answers = this.collectAnswers();

    const res = await fetch("/api/build_prompt", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        task,
        files,
        include_tree,
        chunk_size,
        goal_step: this.goalStep,
        answers,
        applied_log: this.appliedLog,
      }),
    });
    const data = await res.json();
    document.getElementById("generatedPrompt").value = data.full_prompt;
    document.getElementById("promptMeta").textContent =
      `${data.chars.toLocaleString()} chars (~${data.est_tokens.toLocaleString()} tokens)`;

    const btns = document.getElementById("copyButtons");
    btns.innerHTML = "";
    data.parts.forEach((part, idx) => {
      const b = document.createElement("button");
      b.className = "btn success";
      const label = data.parts.length === 1 ? "Copy Prompt" : `Copy Part ${idx + 1}/${data.parts.length}`;
      b.textContent = label;
      b.onclick = async () => {
        await navigator.clipboard.writeText(part);
        this.toast(`${label} copied!`);
        if (document.getElementById("autoUnselect").checked) {
          this.selected.clear();
          this.renderFiles();
          this.renderChips();
        }
      };
      btns.appendChild(b);
    });

    const triggerAiHandoffPopup = (copiedOk) => {
      const firstLabel = data.parts.length === 1 ? "Prompt" : `Part 1/${data.parts.length}`;
      this.showPopup({
        type: "red",
        title: copiedOk
          ? `${firstLabel} Copied — Go Paste in AI & Copy Reply`
          : "Prompt Ready — Copy & Paste in AI Chat",
        message: "1) Paste the prompt into your AI chat. 2) Copy the AI's response. 3) Click Done below to auto-apply and advance.",
        actions: [
          {
            label: "Copy Prompt Again",
            cls: "ghost",
            onClick: async () => {
              await navigator.clipboard.writeText(data.parts[0]);
              triggerAiHandoffPopup(true);
            },
          },
          {
            label: "Done (Paste & Run Next Step)",
            cls: "danger",
            onClick: async () => {
              const aiBox = document.getElementById("aiResponse");
              this.setStage("paste");
              try {
                const clipText = await navigator.clipboard.readText();
                if (clipText && clipText.trim() && clipText.trim() !== data.parts[0].trim()) {
                  aiBox.value = clipText;
                  await this.runOps(true);
                  return;
                }
              } catch (e) {
                // Fallback if clipboard read permission is blocked
              }
              if (aiBox.value.trim()) {
                await this.runOps(true);
              } else {
                aiBox.focus();
                this.showPopup({
                  type: "red",
                  title: "Paste AI Response Below",
                  message: "Press Ctrl+V inside the response box (or copy the AI reply first and click Done again).",
                });
              }
            },
          },
        ],
      });
    };

    if (data.parts && data.parts.length > 0) {
      try {
        await navigator.clipboard.writeText(data.parts[0]);
        if (document.getElementById("autoUnselect").checked) {
          this.selected.clear();
          this.renderFiles();
          this.renderChips();
        }
        triggerAiHandoffPopup(true);
      } catch (e) {
        triggerAiHandoffPopup(false);
      }
    }

    this.setGoalBadge("WAITING REPLY", "active");
    this.setStage("paste");
  },

  renderQuestions(questions) {
    this.pendingQuestions = questions || [];
    const box = document.getElementById("questionsOut");
    box.innerHTML = "";
    if (!this.pendingQuestions.length) return;

    this.pendingQuestions.forEach((q, idx) => {
      const card = document.createElement("div");
      card.className = "qa-card";
      const title = document.createElement("div");
      title.className = "qa-title";
      title.textContent = q.question;
      card.appendChild(title);

      (q.options || []).forEach((opt) => {
        const lbl = document.createElement("label");
        lbl.className = "qa-opt";
        const r = document.createElement("input");
        r.type = "radio";
        r.name = `qa_${idx}`;
        r.value = opt;
        r.onchange = () => {
          if (this.pendingQuestions.length === 1) {
            this.submitAnswersAndAdvance();
          }
        };
        lbl.append(r, document.createTextNode(opt));
        card.appendChild(lbl);
      });

      const custom = document.createElement("input");
      custom.id = `qa_custom_${idx}`;
      custom.placeholder = "Or type a custom answer and press Enter...";
      custom.onkeydown = (e) => {
        if (e.key === "Enter") {
          e.preventDefault();
          this.submitAnswersAndAdvance();
        }
      };
      card.appendChild(custom);
      box.appendChild(card);
    });

    const submitRow = document.createElement("div");
    submitRow.className = "row";
    const btn = document.createElement("button");
    btn.className = "btn primary";
    btn.textContent = "Send Answers & Copy Next Prompt →";
    btn.onclick = () => this.submitAnswersAndAdvance();
    submitRow.appendChild(btn);
    box.appendChild(submitRow);
  },

  async submitAnswersAndAdvance() {
    this.goalStep += 1;
    await this.buildPrompt(true);
    document.getElementById("aiResponse").value = "";
    this.renderQuestions([]);
    this.toast(`Step ${this.goalStep} prompt with answers copied!`);
  },

  async runOps(apply) {
    const text = document.getElementById("aiResponse").value;
    let fallback_path = document.getElementById("fallbackFile").value.trim();
    if (!fallback_path && this.selected.size === 1) {
      fallback_path = Array.from(this.selected.keys())[0];
    }

    const res = await fetch("/api/apply", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text, apply, fallback_path }),
    });
    const data = await res.json();

    if (data.plan && data.plan.length) {
      this.renderPlan(data.plan);
    }

    const hasQuestions = (data.questions || []).length > 0;
    const hasNeedFiles = (data.need_files || []).length > 0;

    this.renderQuestions(data.questions || []);

    const out = document.getElementById("diffOut");
    out.innerHTML = "";
    const results = data.results || [];
    document.getElementById("applyMeta").textContent =
      `${results.length} edit(s) · ${(data.need_files || []).length} file req(s) · ${(data.questions || []).length} question(s)`;

    let appliedCount = 0;
    let errorCount = 0;
    results.forEach((r) => {
      const isApplied = apply && r.status === "applied";
      const card = document.createElement("details");
      card.className = "diff-file";
      card.open = !isApplied;

      const hdr = document.createElement("summary");
      hdr.className = `diff-header ${r.status}`;
      hdr.style.cursor = "pointer";
      hdr.textContent = `${isApplied ? "▸" : "▾"} [${r.status.toUpperCase()}] ${r.path}`;
      card.ontoggle = () => {
        hdr.textContent = `${card.open ? "▾" : "▸"} [${r.status.toUpperCase()}] ${r.path}`;
      };
      card.appendChild(hdr);

      const body = document.createElement("div");
      body.className = "diff-body";
      if (r.message) {
        const line = document.createElement("div");
        line.className = "dline del";
        line.textContent = r.message;
        body.appendChild(line);
      } else if (r.diff_lines && r.diff_lines.length) {
        r.diff_lines.forEach((dl) => {
          const line = document.createElement("div");
          line.className = `dline ${dl.kind}`;
          line.textContent = dl.text;
          body.appendChild(line);
        });
      } else {
        const line = document.createElement("div");
        line.className = "dline meta";
        line.textContent = "(no text changes)";
        body.appendChild(line);
      }
      card.appendChild(body);
      out.appendChild(card);

      if (isApplied) {
        appliedCount += 1;
        this.appliedLog.push(`Step ${this.goalStep}: updated ${r.path}`);
      } else if (r.status === "error") {
        errorCount += 1;
      }
    });

    const applyBtn = document.getElementById("applyBtn");
    if (applyBtn) {
      const autoOn = document.getElementById("autoProcessPaste").checked;
      applyBtn.classList.toggle("hidden", autoOn && appliedCount > 0 && errorCount === 0);
    }

    if (apply && appliedCount > 0) {
      await this.loadFiles();
    }

    // Handle AI-requested files automatically
    if (hasNeedFiles) {
      data.need_files.forEach((nf) => {
        const match = this.files.find((f) => f.path === nf.path);
        this.selected.set(nf.path, {
          path: nf.path,
          mode: nf.mode || "full",
          start: nf.start || "",
          end: nf.end || "",
          tokens: match ? match.est_tokens : 500,
        });
      });
      this.renderFiles();
      this.renderChips();

      if (!hasQuestions) {
        this.goalStep += 1;
        await this.buildPrompt(true);
        document.getElementById("aiResponse").value = "";
        this.setGoalBadge("WAITING NEXT", "active");
        this.toast(`Step ${this.goalStep}: copied ${data.need_files.length} requested file(s)!`);
        return;
      }
    }

    // Automatically advance to next step when AI indicates APPLIED_NEXT
    if (apply && data.status_flag === "APPLIED_NEXT" && !hasQuestions && errorCount === 0) {
      this.goalStep += 1;
      await this.buildPrompt(true);
      document.getElementById("aiResponse").value = "";
      this.setGoalBadge("WAITING NEXT", "active");
      this.toast(`Applied ${appliedCount} file(s) & copied Step ${this.goalStep} prompt!`);
      return;
    }

    if (data.status_flag === "DONE") {
      this.goalFinished = true;
      this.selected.clear();
      this.renderFiles();
      this.renderChips();
      this.setGoalBadge("DONE", "done");
      this.setStage("paste");
      this.showPopup({
        type: "success",
        title: "Goal Completed!",
        message: appliedCount > 0
          ? `Successfully applied ${appliedCount} file(s). Expand any file below to review its diff.`
          : "All steps for this goal are complete.",
        actions: [
          {
            label: "Start New Goal",
            cls: "success",
            onClick: () => this.resetGoal(),
          },
        ],
      });
    } else if (hasQuestions || data.status_flag === "NEED_MORE" || data.status_flag === "APPLIED_NEXT") {
      this.setGoalBadge("WAITING INPUT", "active");
      if (hasQuestions) {
        this.showPopup({
          type: "info",
          title: "AI Needs Your Input",
          message: "Choose an option below (or type a custom answer) to generate and copy the next prompt.",
        });
      }
    } else if (apply && appliedCount > 0) {
      this.showPopup({
        type: "success",
        title: `Applied ${appliedCount} File(s)`,
        message: "Changes saved to disk. Expand any file below to inspect the diff.",
      });
    } else if (errorCount > 0) {
      this.showPopup({
        type: "red",
        title: "Patch Error",
        message: "One or more edits could not be applied. Check the details below.",
      });
    }
  },

  // Code Editor Modal
  async openEditor(relPath) {
    const res = await fetch(`/api/file?path=${encodeURIComponent(relPath)}`);
    const data = await res.json();
    if (!res.ok) return this.toast(data.error || "Failed to open file");

    this.editingPath = relPath;
    document.getElementById("editorTitle").textContent = relPath;
    const ext = relPath.includes(".") ? relPath.split(".").pop().toUpperCase() : "TEXT";
    document.getElementById("editorLangBadge").textContent = ext;

    const area = document.getElementById("editorCode");
    area.value = data.content;
    this.syncEditorGutter();
    document.getElementById("editorModal").classList.remove("hidden");
    area.focus();
  },

  closeEditor() {
    document.getElementById("editorModal").classList.add("hidden");
    this.editingPath = "";
  },

  syncEditorGutter() {
    const area = document.getElementById("editorCode");
    const gutter = document.getElementById("editorLines");
    const lineCount = (area.value.match(/\n/g) || []).length + 1;
    const nums = [];
    for (let i = 1; i <= lineCount; i++) nums.push(i);
    gutter.textContent = nums.join("\n");
  },

  syncEditorScroll() {
    const area = document.getElementById("editorCode");
    const gutter = document.getElementById("editorLines");
    gutter.scrollTop = area.scrollTop;
  },

  prettifyEditor() {
    const area = document.getElementById("editorCode");
    const ext = this.editingPath.split(".").pop().toLowerCase();
    try {
      if (ext === "json") {
        area.value = JSON.stringify(JSON.parse(area.value), null, 2);
        this.syncEditorGutter();
        return this.toast("Formatted JSON");
      }
      // Clean trailing spaces, normalize tabs to 2/4 spaces, and ensure single trailing newline
      const indent = ext === "py" ? "    " : "  ";
      const cleaned = area.value
        .replace(/\r\n/g, "\n")
        .split("\n")
        .map((line) => line.replace(/\t/g, indent).replace(/[ \t]+$/, ""))
        .join("\n")
        .replace(/\n{3,}/g, "\n\n")
        .trimEnd() + "\n";
      area.value = cleaned;
      this.syncEditorGutter();
      this.toast("Prettified whitespace & indentation");
    } catch (e) {
      this.toast(`Format error: ${e.message}`);
    }
  },

  async saveEditor() {
    if (!this.editingPath) return;
    const content = document.getElementById("editorCode").value;
    const res = await fetch("/api/file", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path: this.editingPath, content }),
    });
    const data = await res.json();
    if (!res.ok) return this.toast(data.error || "Save failed");
    await this.loadFiles();
    this.toast(`Saved ${this.editingPath}`);
  },

  init() {
    // Clear browser-restored form inputs on page reload so Smart Select never auto-picks stale goals
    document.getElementById("task").value = "";
    document.getElementById("aiResponse").value = "";
    document.getElementById("generatedPrompt").value = "";
    document.getElementById("fallbackFile").value = "";
    this.setStage("goal");

    const autoPasteChk = document.getElementById("autoProcessPaste");
    const applyBtn = document.getElementById("applyBtn");
    const syncApplyBtnVisibility = () => {
      if (applyBtn) applyBtn.classList.toggle("hidden", autoPasteChk.checked);
    };
    syncApplyBtnVisibility();
    autoPasteChk.addEventListener("change", syncApplyBtnVisibility);

    const aiBox = document.getElementById("aiResponse");
    aiBox.addEventListener("paste", () => {
      if (!autoPasteChk.checked) return;
      setTimeout(() => {
        if (aiBox.value.trim()) this.runOps(true);
      }, 60);
    });

    const taskBox = document.getElementById("task");
    let smartTimer = null;
    taskBox.addEventListener("input", () => {
      if (this.goalFinished) this.goalFinished = false;
      if (!document.getElementById("autoSelectSmart").checked) return;
      clearTimeout(smartTimer);
      smartTimer = setTimeout(() => {
        if (
          this.stage === "goal" &&
          !this.goalFinished &&
          this.goalStep === 1 &&
          taskBox.value.trim().length >= 8 &&
          this.selected.size === 0
        ) {
          this.smartSelect();
        }
      }, 650);
    });

    const editorArea = document.getElementById("editorCode");
    editorArea.addEventListener("keydown", (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "s") {
        e.preventDefault();
        this.saveEditor();
      } else if (e.key === "Tab") {
        e.preventDefault();
        const start = editorArea.selectionStart;
        const end = editorArea.selectionEnd;
        const indent = this.editingPath.endsWith(".py") ? "    " : "  ";
        editorArea.value = editorArea.value.substring(0, start) + indent + editorArea.value.substring(end);
        editorArea.selectionStart = editorArea.selectionEnd = start + indent.length;
        this.syncEditorGutter();
      }
    });
  },
};

App.init();
App.loadFiles();

const App = {
  files: [],
  selected: new Map(), // path -> { path, mode, start, end, tokens }
  expandedDirs: new Set(),
  browseParent: "",
  goalStep: 1,
  goalFinished: false,
  stage: "goal", // "goal" | "paste"
  appliedLog: [],
  pendingQuestions: [],
  planTasks: [],
  editingPath: "",

  showPopup({ type = "info", title = "", message = "", actions = [] }) {
    const box = document.getElementById("inlinePopup");
    const iconEl = document.getElementById("inlinePopupIcon");
    const titleEl = document.getElementById("inlinePopupTitle");
    const msgEl = document.getElementById("inlinePopupMsg");
    const actEl = document.getElementById("inlinePopupActions");
    if (!box) return;

    box.className = `inline-popup ${type}`;
    const icons = { info: "ℹ️", success: "✅", red: "🚨" };
    iconEl.textContent = icons[type] || "ℹ️";
    titleEl.textContent = title || (type === "red" ? "Action Required: Paste in AI Chat" : "Status");
    msgEl.textContent = message;

    actEl.innerHTML = "";
    actions.forEach((act) => {
      const b = document.createElement("button");
      b.className = `btn ${act.cls || "primary"}`;
      b.textContent = act.label;
      b.onclick = act.onClick;
      actEl.appendChild(b);
    });
  },

  toast(msg, type = "info") {
    this.showPopup({
      type,
      title: type === "success" ? "Completed" : "Status Update",
      message: msg,
    });
  },

  openOptionsModal() {
    document.getElementById("optionsModal").classList.remove("hidden");
  },

  closeOptionsModal() {
    document.getElementById("optionsModal").classList.add("hidden");
  },

  openChoiceModal({ title, description = "", options = [] }) {
    document.getElementById("choiceModalTitle").textContent = title;
    document.getElementById("choiceModalDesc").textContent = description;
    const body = document.getElementById("choiceModalBody");
    body.innerHTML = "";

    options.forEach((opt) => {
      const btn = document.createElement("button");
      btn.className = "choice-option-btn";
      const lbl = document.createElement("span");
      lbl.textContent = opt.label;
      const hint = document.createElement("span");
      hint.className = "muted";
      hint.textContent = opt.hint || "";
      btn.append(lbl, hint);
      btn.onclick = () => {
        this.closeChoiceModal();
        if (opt.onSelect) opt.onSelect();
      };
      body.appendChild(btn);
    });

    document.getElementById("choiceModal").classList.remove("hidden");
  },

  closeChoiceModal() {
    document.getElementById("choiceModal").classList.add("hidden");
  },

  setGoalBadge(stateText, cls = "") {
    const b = document.getElementById("goalBadge");
    b.textContent = `Goal: Step ${this.goalStep} (${stateText})`;
    b.className = `badge goal ${cls}`;
  },

  setStage(stage) {
    this.stage = stage;
    const promptCard = document.getElementById("stagePromptCard");
    const pasteCard = document.getElementById("stagePasteCard");
    const switchBtn = document.getElementById("switchToPasteBtn");

    if (stage === "goal") {
      promptCard.classList.remove("hidden");
      pasteCard.classList.add("hidden");
      if (this.goalStep > 1 || document.getElementById("generatedPrompt").value.trim()) {
        switchBtn.classList.remove("hidden");
      } else {
        switchBtn.classList.add("hidden");
      }
    } else {
      promptCard.classList.add("hidden");
      pasteCard.classList.remove("hidden");
      const pasteArea = document.getElementById("pasteInputArea");
      const doneActions = document.getElementById("doneActions");
      if (this.goalFinished) {
        pasteArea.classList.add("hidden");
        doneActions.classList.remove("hidden");
      } else {
        pasteArea.classList.remove("hidden");
        doneActions.classList.add("hidden");
      }
    }
  },

  togglePromptPreview() {
    document.getElementById("promptPreviewWrap").classList.toggle("hidden");
  },

  resetGoal() {
    this.goalStep = 1;
    this.goalFinished = false;
    this.appliedLog = [];
    this.pendingQuestions = [];
    this.planTasks = [];
    this.selected.clear();

    document.getElementById("task").value = "";
    document.getElementById("generatedPrompt").value = "";
    document.getElementById("promptMeta").textContent = "";
    document.getElementById("copyButtons").innerHTML = "";
    document.getElementById("questionsOut").innerHTML = "";
    document.getElementById("diffOut").innerHTML = "";
    document.getElementById("aiResponse").value = "";
    document.getElementById("applyMeta").textContent = "";
    document.getElementById("promptPreviewWrap").classList.add("hidden");

    const autoPasteChk = document.getElementById("autoProcessPaste");
    const applyBtn = document.getElementById("applyBtn");
    if (applyBtn && autoPasteChk) {
      applyBtn.classList.toggle("hidden", autoPasteChk.checked);
    }

    this.renderPlan([]);
    this.renderFiles();
    this.renderChips();
    this.setGoalBadge("IDLE");
    this.setStage("goal");
    this.showPopup({
      type: "info",
      title: "Ready for a New Goal",
      message: "Describe what you want to build or fix, or double-click any file on the left to inspect/edit.",
    });
  },

  async loadFiles() {
    const res = await fetch("/api/files");
    const data = await res.json();
    this.files = data.files || [];
    this.renderFiles();
  },

  async setProject(customPath = null) {
    const path = customPath !== null ? customPath : document.getElementById("projPath").value;
    const res = await fetch("/api/project", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path }),
    });
    const data = await res.json();
    if (!res.ok) return this.toast(data.error);
    document.getElementById("projPath").value = data.root;
    this.expandedDirs.clear();
    this.resetGoal();
    await this.loadFiles();
    this.toast("Project loaded");
  },

  async smartSelect() {
    if (this.goalFinished) return;
    const task = document.getElementById("task").value.trim();
    if (!task) return this.toast("Enter a task first so Smart Select can match files.");
    const res = await fetch("/api/smart_select", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ task }),
    });
    const data = await res.json();
    this.selected.clear();
    (data.selected || []).forEach((s) => {
      this.selected.set(s.path, { path: s.path, mode: s.mode, start: "", end: "", tokens: s.tokens || 500 });
    });
    this.renderFiles();
    this.renderChips();
    this.toast(`Smart Select picked ${this.selected.size} file(s)`);
  },

  async openBrowser() {
    document.getElementById("browserModal").classList.remove("hidden");
    await this.browseTo(document.getElementById("projPath").value);
  },

  closeBrowser() {
    document.getElementById("browserModal").classList.add("hidden");
  },

  async browseTo(path) {
    const res = await fetch(`/api/browse?path=${encodeURIComponent(path || "")}`);
    const data = await res.json();
    document.getElementById("browsePath").value = data.current;
    this.browseParent = data.parent || "";
    document.getElementById("upBtn").disabled = !this.browseParent;

    const drives = document.getElementById("driveBar");
    drives.innerHTML = "";
    (data.drives || []).forEach((d) => {
      const b = document.createElement("button");
      b.className = "btn ghost";
      b.textContent = d;
      b.onclick = () => this.browseTo(d);
      drives.appendChild(b);
    });

    const list = document.getElementById("dirList");
    list.innerHTML = "";
    (data.dirs || []).forEach((d) => {
      const row = document.createElement("div");
      row.className = "fitem";
      row.textContent = "📁 " + d.name;
      row.onclick = () => this.browseTo(d.path);
      list.appendChild(row);
    });
  },

  browseUp() {
    if (this.browseParent) this.browseTo(this.browseParent);
  },

  async selectBrowsed() {
    const chosen = document.getElementById("browsePath").value;
    this.closeBrowser();
    await this.setProject(chosen);
  },

  buildFileTree(files) {
    const root = { name: "", path: "", folders: new Map(), files: [] };
    files.forEach((f) => {
      const parts = f.path.split("/");
      let node = root;
      for (let i = 0; i < parts.length - 1; i++) {
        const seg = parts[i];
        const nextPath = node.path ? `${node.path}/${seg}` : seg;
        if (!node.folders.has(seg)) {
          node.folders.set(seg, { name: seg, path: nextPath, folders: new Map(), files: [] });
        }
        node = node.folders.get(seg);
      }
      node.files.push({ ...f, name: parts[parts.length - 1] });
    });
    return root;
  },

  collectFolderFiles(node, acc = []) {
    node.files.forEach((f) => acc.push(f));
    node.folders.forEach((sub) => this.collectFolderFiles(sub, acc));
    return acc;
  },

  renderTreeNode(node, container, isFilterActive) {
    const sortedFolders = Array.from(node.folders.values()).sort((a, b) => a.name.localeCompare(b.name));
    sortedFolders.forEach((folder) => {
      const descendantFiles = this.collectFolderFiles(folder, []);
      if (!descendantFiles.length) return;

      const wrap = document.createElement("div");
      wrap.className = "tree-folder";

      const row = document.createElement("div");
      row.className = "tree-row";

      const isCollapsed = !isFilterActive && !this.expandedDirs.has(folder.path);
      const caret = document.createElement("span");
      caret.className = "tree-caret";
      caret.textContent = isCollapsed ? "▸" : "▾";

      const cb = document.createElement("input");
      cb.type = "checkbox";
      const selectedCount = descendantFiles.filter((f) => this.selected.has(f.path)).length;
      cb.checked = selectedCount > 0 && selectedCount === descendantFiles.length;
      cb.indeterminate = selectedCount > 0 && selectedCount < descendantFiles.length;
      cb.onclick = (e) => e.stopPropagation();
      cb.onchange = () => {
        descendantFiles.forEach((f) => {
          if (cb.checked) {
            const mode = f.est_tokens > 4000 ? "outline" : "full";
            this.selected.set(f.path, { path: f.path, mode, start: "", end: "", tokens: f.est_tokens });
          } else {
            this.selected.delete(f.path);
          }
        });
        this.renderFiles();
        this.renderChips();
      };

      const lbl = document.createElement("span");
      lbl.className = "tree-folder-lbl";
      lbl.textContent = `📁 ${folder.name}`;

      row.onclick = () => {
        if (this.collapsedDirs.has(folder.path)) {
          this.collapsedDirs.delete(folder.path);
        } else {
          this.collapsedDirs.add(folder.path);
        }
        this.renderFiles();
      };

      row.append(caret, cb, lbl);
      wrap.appendChild(row);

      const childrenBox = document.createElement("div");
      childrenBox.className = `tree-children${isCollapsed ? " collapsed" : ""}`;
      this.renderTreeNode(folder, childrenBox, isFilterActive);
      wrap.appendChild(childrenBox);
      container.appendChild(wrap);
    });

    const sortedFiles = [...node.files].sort((a, b) => a.name.localeCompare(b.name));
    sortedFiles.forEach((f) => {
      const row = document.createElement("div");
      row.className = "tree-row";
      row.title = "Double-click to view or edit file";

      const spacer = document.createElement("span");
      spacer.className = "tree-caret";
      spacer.textContent = "";

      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.checked = this.selected.has(f.path);
      cb.onclick = (e) => e.stopPropagation();
      cb.onchange = () => {
        if (cb.checked) {
          const defaultMode = f.est_tokens > 4000 ? "outline" : "full";
          this.selected.set(f.path, { path: f.path, mode: defaultMode, start: "", end: "", tokens: f.est_tokens });
        } else {
          this.selected.delete(f.path);
        }
        this.renderFiles();
        this.renderChips();
      };

      const name = document.createElement("span");
      name.className = "tree-file-lbl";
      name.textContent = f.name;

      const meta = document.createElement("span");
      meta.className = "fmeta";
      meta.textContent = `~${f.est_tokens}t`;

      row.onclick = () => {
        cb.checked = !cb.checked;
        cb.onchange();
      };
      row.ondblclick = (e) => {
        e.stopPropagation();
        this.openEditor(f.path);
      };

      row.append(spacer, cb, name, meta);
      container.appendChild(row);
    });
  },

  renderFiles() {
    const q = document.getElementById("filter").value.toLowerCase().trim();
    const list = document.getElementById("fileList");
    list.innerHTML = "";

    const filtered = q
      ? this.files.filter((f) => f.path.toLowerCase().includes(q))
      : this.files;

    const tree = this.buildFileTree(filtered);
    this.renderTreeNode(tree, list, Boolean(q));
    this.updateStats();
  },

  renderChips() {
    const box = document.getElementById("selectedChips");
    box.innerHTML = "";
    this.selected.forEach((spec, path) => {
      const chip = document.createElement("div");
      chip.className = "chip";
      const lbl = document.createElement("span");
      lbl.textContent = path;

      const modeBtn = document.createElement("button");
      modeBtn.className = "btn ghost";
      modeBtn.style.padding = "2px 8px";
      modeBtn.style.fontSize = "11px";
      modeBtn.textContent = `${spec.mode} ▾`;
      modeBtn.onclick = () => {
        this.openChoiceModal({
          title: `Context Mode for ${path}`,
          description: "Choose how much of this file to include in the AI prompt:",
          options: [
            {
              label: "Full File",
              hint: `~${spec.tokens} tokens`,
              onSelect: () => {
                spec.mode = "full";
                this.renderChips();
                this.updateStats();
                this.toast(`${path} set to full mode`);
              },
            },
            {
              label: "Outline Only (Save ~80% Tokens)",
              hint: `~${Math.round(spec.tokens * 0.2)} tokens`,
              onSelect: () => {
                spec.mode = "outline";
                this.renderChips();
                this.updateStats();
                this.toast(`${path} set to outline mode`);
              },
            },
            {
              label: "Specific Line Range",
              hint: "Choose start & end lines",
              onSelect: () => {
                spec.mode = "range";
                this.renderChips();
                this.updateStats();
              },
            },
            {
              label: "Remove File from Selection",
              hint: "Exclude",
              onSelect: () => {
                this.selected.delete(path);
                this.renderFiles();
                this.renderChips();
              },
            },
          ],
        });
      };
      chip.append(lbl, modeBtn);

      if (spec.mode === "range") {
        const sIn = document.createElement("input");
        sIn.className = "rng";
        sIn.placeholder = "start";
        sIn.value = spec.start;
        sIn.oninput = () => (spec.start = parseInt(sIn.value) || "");
        const eIn = document.createElement("input");
        eIn.className = "rng";
        eIn.placeholder = "end";
        eIn.value = spec.end;
        eIn.oninput = () => (spec.end = parseInt(eIn.value) || "");
        chip.append(sIn, eIn);
      }
      box.appendChild(chip);
    });
  },

  updateStats() {
    document.getElementById("fileStats").textContent = `${this.selected.size} / ${this.files.length} files`;
    let total = 0;
    this.selected.forEach((s) => {
      total += s.mode === "outline" ? Math.round(s.tokens * 0.2) : s.tokens;
    });
    document.getElementById("selectedTokens").textContent = `~${total.toLocaleString()} tokens`;
  },

  toggleAll(on) {
    const q = document.getElementById("filter").value.toLowerCase();
    this.files.forEach((f) => {
      if (!q || f.path.toLowerCase().includes(q)) {
        if (on) {
          const mode = f.est_tokens > 4000 ? "outline" : "full";
          this.selected.set(f.path, { path: f.path, mode, start: "", end: "", tokens: f.est_tokens });
        } else {
          this.selected.delete(f.path);
        }
      }
    });
    this.renderFiles();
    this.renderChips();
  },

  collectAnswers() {
    const answers = [];
    this.pendingQuestions.forEach((q, idx) => {
      const checked = document.querySelector(`input[name="qa_${idx}"]:checked`);
      const custom = document.getElementById(`qa_custom_${idx}`).value.trim();
      const ans = custom || (checked ? checked.value : "");
      if (ans) answers.push({ question: q.question, answer: ans });
    });
    return answers;
  },

  renderPlan(planItems) {
    const panel = document.getElementById("planPanel");
    const box = document.getElementById("planOut");
    const meta = document.getElementById("planMeta");

    if (planItems && planItems.length) {
      this.planTasks = planItems;
    }

    if (!this.planTasks.length) {
      panel.classList.add("hidden");
      panel.open = false;
      box.innerHTML = "";
      return;
    }

    panel.classList.remove("hidden");
    box.innerHTML = "";
    let totalCount = 0;
    let doneCount = 0;

    this.planTasks.forEach((item) => {
      totalCount += 1;
      if (item.done) doneCount += 1;

      const wrap = document.createElement("div");
      wrap.className = "plan-item";

      const mainRow = document.createElement("label");
      mainRow.className = "plan-main";
      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.style.width = "auto";
      cb.checked = Boolean(item.done);
      const txt = document.createElement("span");
      txt.textContent = item.text;
      if (item.done) txt.className = "plan-done";
      cb.onchange = () => {
        item.done = cb.checked;
        txt.className = cb.checked ? "plan-done" : "";
      };
      mainRow.append(cb, txt);
      wrap.appendChild(mainRow);

      if (item.subtasks && item.subtasks.length) {
        const subBox = document.createElement("div");
        subBox.className = "plan-sublist";
        item.subtasks.forEach((sub) => {
          totalCount += 1;
          if (sub.done) doneCount += 1;
          const subRow = document.createElement("label");
          subRow.className = "plan-sub";
          const scb = document.createElement("input");
          scb.type = "checkbox";
          scb.style.width = "auto";
          scb.checked = Boolean(sub.done);
          const stxt = document.createElement("span");
          stxt.textContent = sub.text;
          if (sub.done) stxt.className = "plan-done";
          scb.onchange = () => {
            sub.done = scb.checked;
            stxt.className = scb.checked ? "plan-done" : "";
          };
          subRow.append(scb, stxt);
          subBox.appendChild(subRow);
        });
        wrap.appendChild(subBox);
      }
      box.appendChild(wrap);
    });

    meta.textContent = `${doneCount}/${totalCount} completed (click to expand)`;
  },

  async buildPrompt(isAutoNext = false) {
    const task = document.getElementById("task").value.trim();
    if (!task) return this.toast("Describe your goal first.");

    this.goalFinished = false;

    if (
      !isAutoNext &&
      this.goalStep === 1 &&
      this.selected.size === 0 &&
      document.getElementById("autoSelectSmart").checked
    ) {
      await this.smartSelect();
    }

    const include_tree = document.getElementById("includeTree").checked;
    const chunk_size = parseInt(document.getElementById("chunkSize").value) || 120000;
    const files = Array.from(this.selected.values());
    const answers = this.collectAnswers();

    const res = await fetch("/api/build_prompt", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        task,
        files,
        include_tree,
        chunk_size,
        goal_step: this.goalStep,
        answers,
        applied_log: this.appliedLog,
      }),
    });
    const data = await res.json();
    document.getElementById("generatedPrompt").value = data.full_prompt;
    document.getElementById("promptMeta").textContent =
      `${data.chars.toLocaleString()} chars (~${data.est_tokens.toLocaleString()} tokens)`;

    const btns = document.getElementById("copyButtons");
    btns.innerHTML = "";
    data.parts.forEach((part, idx) => {
      const b = document.createElement("button");
      b.className = "btn success";
      const label = data.parts.length === 1 ? "Copy Prompt" : `Copy Part ${idx + 1}/${data.parts.length}`;
      b.textContent = label;
      b.onclick = async () => {
        await navigator.clipboard.writeText(part);
        this.toast(`${label} copied!`);
        if (document.getElementById("autoUnselect").checked) {
          this.selected.clear();
          this.renderFiles();
          this.renderChips();
        }
      };
      btns.appendChild(b);
    });

    const triggerAiHandoffPopup = (copiedOk) => {
      const firstLabel = data.parts.length === 1 ? "Prompt" : `Part 1/${data.parts.length}`;
      this.showPopup({
        type: "red",
        title: copiedOk
          ? `${firstLabel} Copied — Go Paste in AI & Copy Reply`
          : "Prompt Ready — Copy & Paste in AI Chat",
        message: "1) Paste the prompt into your AI chat. 2) Copy the AI's response. 3) Click Done below to auto-apply and advance.",
        actions: [
          {
            label: "Copy Prompt Again",
            cls: "ghost",
            onClick: async () => {
              await navigator.clipboard.writeText(data.parts[0]);
              triggerAiHandoffPopup(true);
            },
          },
          {
            label: "Done (Paste & Run Next Step)",
            cls: "danger",
            onClick: async () => {
              const aiBox = document.getElementById("aiResponse");
              this.setStage("paste");
              try {
                const clipText = await navigator.clipboard.readText();
                if (clipText && clipText.trim() && clipText.trim() !== data.parts[0].trim()) {
                  aiBox.value = clipText;
                  await this.runOps(true);
                  return;
                }
              } catch (e) {
                // Fallback if clipboard read permission is blocked
              }
              if (aiBox.value.trim()) {
                await this.runOps(true);
              } else {
                aiBox.focus();
                this.showPopup({
                  type: "red",
                  title: "Paste AI Response Below",
                  message: "Press Ctrl+V inside the response box (or copy the AI reply first and click Done again).",
                });
              }
            },
          },
        ],
      });
    };

    if (data.parts && data.parts.length > 0) {
      try {
        await navigator.clipboard.writeText(data.parts[0]);
        if (document.getElementById("autoUnselect").checked) {
          this.selected.clear();
          this.renderFiles();
          this.renderChips();
        }
        triggerAiHandoffPopup(true);
      } catch (e) {
        triggerAiHandoffPopup(false);
      }
    }

    this.setGoalBadge("WAITING REPLY", "active");
    this.setStage("paste");
  },

  renderQuestions(questions) {
    this.pendingQuestions = questions || [];
    const box = document.getElementById("questionsOut");
    box.innerHTML = "";
    if (!this.pendingQuestions.length) return;

    this.pendingQuestions.forEach((q, idx) => {
      const card = document.createElement("div");
      card.className = "qa-card";
      const title = document.createElement("div");
      title.className = "qa-title";
      title.textContent = q.question;
      card.appendChild(title);

      (q.options || []).forEach((opt) => {
        const lbl = document.createElement("label");
        lbl.className = "qa-opt";
        const r = document.createElement("input");
        r.type = "radio";
        r.name = `qa_${idx}`;
        r.value = opt;
        r.onchange = () => {
          if (this.pendingQuestions.length === 1) {
            this.submitAnswersAndAdvance();
          }
        };
        lbl.append(r, document.createTextNode(opt));
        card.appendChild(lbl);
      });

      const custom = document.createElement("input");
      custom.id = `qa_custom_${idx}`;
      custom.placeholder = "Or type a custom answer and press Enter...";
      custom.onkeydown = (e) => {
        if (e.key === "Enter") {
          e.preventDefault();
          this.submitAnswersAndAdvance();
        }
      };
      card.appendChild(custom);
      box.appendChild(card);
    });

    const submitRow = document.createElement("div");
    submitRow.className = "row";
    const btn = document.createElement("button");
    btn.className = "btn primary";
    btn.textContent = "Send Answers & Copy Next Prompt →";
    btn.onclick = () => this.submitAnswersAndAdvance();
    submitRow.appendChild(btn);
    box.appendChild(submitRow);
  },

  async submitAnswersAndAdvance() {
    this.goalStep += 1;
    await this.buildPrompt(true);
    document.getElementById("aiResponse").value = "";
    this.renderQuestions([]);
    this.toast(`Step ${this.goalStep} prompt with answers copied!`);
  },

  async runOps(apply) {
    const text = document.getElementById("aiResponse").value;
    let fallback_path = document.getElementById("fallbackFile").value.trim();
    if (!fallback_path && this.selected.size === 1) {
      fallback_path = Array.from(this.selected.keys())[0];
    }

    const res = await fetch("/api/apply", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text, apply, fallback_path }),
    });
    const data = await res.json();

    if (data.plan && data.plan.length) {
      this.renderPlan(data.plan);
    }

    const hasQuestions = (data.questions || []).length > 0;
    const hasNeedFiles = (data.need_files || []).length > 0;

    this.renderQuestions(data.questions || []);

    const out = document.getElementById("diffOut");
    out.innerHTML = "";
    const results = data.results || [];
    document.getElementById("applyMeta").textContent =
      `${results.length} edit(s) · ${(data.need_files || []).length} file req(s) · ${(data.questions || []).length} question(s)`;

    let appliedCount = 0;
    let errorCount = 0;
    results.forEach((r) => {
      const isApplied = apply && r.status === "applied";
      const card = document.createElement("details");
      card.className = "diff-file";
      card.open = !isApplied;

      const hdr = document.createElement("summary");
      hdr.className = `diff-header ${r.status}`;
      hdr.style.cursor = "pointer";
      hdr.textContent = `${isApplied ? "▸" : "▾"} [${r.status.toUpperCase()}] ${r.path}`;
      card.ontoggle = () => {
        hdr.textContent = `${card.open ? "▾" : "▸"} [${r.status.toUpperCase()}] ${r.path}`;
      };
      card.appendChild(hdr);

      const body = document.createElement("div");
      body.className = "diff-body";
      if (r.message) {
        const line = document.createElement("div");
        line.className = "dline del";
        line.textContent = r.message;
        body.appendChild(line);
      } else if (r.diff_lines && r.diff_lines.length) {
        r.diff_lines.forEach((dl) => {
          const line = document.createElement("div");
          line.className = `dline ${dl.kind}`;
          line.textContent = dl.text;
          body.appendChild(line);
        });
      } else {
        const line = document.createElement("div");
        line.className = "dline meta";
        line.textContent = "(no text changes)";
        body.appendChild(line);
      }
      card.appendChild(body);
      out.appendChild(card);

      if (isApplied) {
        appliedCount += 1;
        this.appliedLog.push(`Step ${this.goalStep}: updated ${r.path}`);
      } else if (r.status === "error") {
        errorCount += 1;
      }
    });

    const applyBtn = document.getElementById("applyBtn");
    if (applyBtn) {
      const autoOn = document.getElementById("autoProcessPaste").checked;
      applyBtn.classList.toggle("hidden", autoOn && appliedCount > 0 && errorCount === 0);
    }

    if (apply && appliedCount > 0) {
      await this.loadFiles();
    }

    // Handle AI-requested files automatically
    if (hasNeedFiles) {
      data.need_files.forEach((nf) => {
        const match = this.files.find((f) => f.path === nf.path);
        this.selected.set(nf.path, {
          path: nf.path,
          mode: nf.mode || "full",
          start: nf.start || "",
          end: nf.end || "",
          tokens: match ? match.est_tokens : 500,
        });
      });
      this.renderFiles();
      this.renderChips();

      if (!hasQuestions) {
        this.goalStep += 1;
        await this.buildPrompt(true);
        document.getElementById("aiResponse").value = "";
        this.setGoalBadge("WAITING NEXT", "active");
        this.toast(`Step ${this.goalStep}: copied ${data.need_files.length} requested file(s)!`);
        return;
      }
    }

    // Automatically advance to next step when AI indicates APPLIED_NEXT
    if (apply && data.status_flag === "APPLIED_NEXT" && !hasQuestions && errorCount === 0) {
      this.goalStep += 1;
      await this.buildPrompt(true);
      document.getElementById("aiResponse").value = "";
      this.setGoalBadge("WAITING NEXT", "active");
      this.toast(`Applied ${appliedCount} file(s) & copied Step ${this.goalStep} prompt!`);
      return;
    }

    if (data.status_flag === "DONE") {
      this.goalFinished = true;
      this.selected.clear();
      this.renderFiles();
      this.renderChips();
      this.setGoalBadge("DONE", "done");
      this.setStage("paste");
      this.showPopup({
        type: "success",
        title: "Goal Completed!",
        message: appliedCount > 0
          ? `Successfully applied ${appliedCount} file(s). Expand any file below to review its diff.`
          : "All steps for this goal are complete.",
        actions: [
          {
            label: "Start New Goal",
            cls: "success",
            onClick: () => this.resetGoal(),
          },
        ],
      });
    } else if (hasQuestions || data.status_flag === "NEED_MORE" || data.status_flag === "APPLIED_NEXT") {
      this.setGoalBadge("WAITING INPUT", "active");
      if (hasQuestions) {
        this.showPopup({
          type: "info",
          title: "AI Needs Your Input",
          message: "Choose an option below (or type a custom answer) to generate and copy the next prompt.",
        });
      }
    } else if (apply && appliedCount > 0) {
      this.showPopup({
        type: "success",
        title: `Applied ${appliedCount} File(s)`,
        message: "Changes saved to disk. Expand any file below to inspect the diff.",
      });
    } else if (errorCount > 0) {
      this.showPopup({
        type: "red",
        title: "Patch Error",
        message: "One or more edits could not be applied. Check the details below.",
      });
    }
  },

  // Code Editor Modal
  async openEditor(relPath) {
    const res = await fetch(`/api/file?path=${encodeURIComponent(relPath)}`);
    const data = await res.json();
    if (!res.ok) return this.toast(data.error || "Failed to open file");

    this.editingPath = relPath;
    document.getElementById("editorTitle").textContent = relPath;
    const ext = relPath.includes(".") ? relPath.split(".").pop().toUpperCase() : "TEXT";
    document.getElementById("editorLangBadge").textContent = ext;

    const area = document.getElementById("editorCode");
    area.value = data.content;
    this.syncEditorGutter();
    document.getElementById("editorModal").classList.remove("hidden");
    area.focus();
  },

  closeEditor() {
    document.getElementById("editorModal").classList.add("hidden");
    this.editingPath = "";
  },

  syncEditorGutter() {
    const area = document.getElementById("editorCode");
    const gutter = document.getElementById("editorLines");
    const lineCount = (area.value.match(/\n/g) || []).length + 1;
    const nums = [];
    for (let i = 1; i <= lineCount; i++) nums.push(i);
    gutter.textContent = nums.join("\n");
  },

  syncEditorScroll() {
    const area = document.getElementById("editorCode");
    const gutter = document.getElementById("editorLines");
    gutter.scrollTop = area.scrollTop;
  },

  prettifyEditor() {
    const area = document.getElementById("editorCode");
    const ext = this.editingPath.split(".").pop().toLowerCase();
    try {
      if (ext === "json") {
        area.value = JSON.stringify(JSON.parse(area.value), null, 2);
        this.syncEditorGutter();
        return this.toast("Formatted JSON");
      }
      // Clean trailing spaces, normalize tabs to 2/4 spaces, and ensure single trailing newline
      const indent = ext === "py" ? "    " : "  ";
      const cleaned = area.value
        .replace(/\r\n/g, "\n")
        .split("\n")
        .map((line) => line.replace(/\t/g, indent).replace(/[ \t]+$/, ""))
        .join("\n")
        .replace(/\n{3,}/g, "\n\n")
        .trimEnd() + "\n";
      area.value = cleaned;
      this.syncEditorGutter();
      this.toast("Prettified whitespace & indentation");
    } catch (e) {
      this.toast(`Format error: ${e.message}`);
    }
  },

  async saveEditor() {
    if (!this.editingPath) return;
    const content = document.getElementById("editorCode").value;
    const res = await fetch("/api/file", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path: this.editingPath, content }),
    });
    const data = await res.json();
    if (!res.ok) return this.toast(data.error || "Save failed");
    await this.loadFiles();
    this.toast(`Saved ${this.editingPath}`);
  },

  init() {
    // Clear browser-restored form inputs on page reload so Smart Select never auto-picks stale goals
    document.getElementById("task").value = "";
    document.getElementById("aiResponse").value = "";
    document.getElementById("generatedPrompt").value = "";
    document.getElementById("fallbackFile").value = "";
    this.setStage("goal");

    const autoPasteChk = document.getElementById("autoProcessPaste");
    const applyBtn = document.getElementById("applyBtn");
    const syncApplyBtnVisibility = () => {
      if (applyBtn) applyBtn.classList.toggle("hidden", autoPasteChk.checked);
    };
    syncApplyBtnVisibility();
    autoPasteChk.addEventListener("change", syncApplyBtnVisibility);

    const aiBox = document.getElementById("aiResponse");
    aiBox.addEventListener("paste", () => {
      if (!autoPasteChk.checked) return;
      setTimeout(() => {
        if (aiBox.value.trim()) this.runOps(true);
      }, 60);
    });

    const taskBox = document.getElementById("task");
    let smartTimer = null;
    taskBox.addEventListener("input", () => {
      if (this.goalFinished) this.goalFinished = false;
      if (!document.getElementById("autoSelectSmart").checked) return;
      clearTimeout(smartTimer);
      smartTimer = setTimeout(() => {
        if (
          this.stage === "goal" &&
          !this.goalFinished &&
          this.goalStep === 1 &&
          taskBox.value.trim().length >= 8 &&
          this.selected.size === 0
        ) {
          this.smartSelect();
        }
      }, 650);
    });

    const editorArea = document.getElementById("editorCode");
    editorArea.addEventListener("keydown", (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "s") {
        e.preventDefault();
        this.saveEditor();
      } else if (e.key === "Tab") {
        e.preventDefault();
        const start = editorArea.selectionStart;
        const end = editorArea.selectionEnd;
        const indent = this.editingPath.endsWith(".py") ? "    " : "  ";
        editorArea.value = editorArea.value.substring(0, start) + indent + editorArea.value.substring(end);
        editorArea.selectionStart = editorArea.selectionEnd = start + indent.length;
        this.syncEditorGutter();
      }
    });
  },
};

App.init();
App.loadFiles();

const App = {
  files: [],
  selected: new Map(), // path -> { path, mode, start, end, tokens }
  expandedDirs: new Set(),
  browseParent: "",
  goalStep: 1,
  goalFinished: false,
  stage: "goal", // "goal" | "paste"
  appliedLog: [],
  pendingQuestions: [],
  planTasks: [],
  editingPath: "",

  showPopup({ type = "info", title = "", message = "", actions = [] }) {
    const box = document.getElementById("inlinePopup");
    const iconEl = document.getElementById("inlinePopupIcon");
    const titleEl = document.getElementById("inlinePopupTitle");
    const msgEl = document.getElementById("inlinePopupMsg");
    const actEl = document.getElementById("inlinePopupActions");
    if (!box) return;

    box.className = `inline-popup ${type}`;
    const icons = { info: "ℹ️", success: "✅", red: "🚨" };
    iconEl.textContent = icons[type] || "ℹ️";
    titleEl.textContent = title || (type === "red" ? "Action Required: Paste in AI Chat" : "Status");
    msgEl.textContent = message;

    actEl.innerHTML = "";
    actions.forEach((act) => {
      const b = document.createElement("button");
      b.className = `btn ${act.cls || "primary"}`;
      b.textContent = act.label;
      b.onclick = act.onClick;
      actEl.appendChild(b);
    });
  },

  toast(msg, type = "info") {
    this.showPopup({
      type,
      title: type === "success" ? "Completed" : "Status Update",
      message: msg,
    });
  },

  openOptionsModal() {
    document.getElementById("optionsModal").classList.remove("hidden");
  },

  closeOptionsModal() {
    document.getElementById("optionsModal").classList.add("hidden");
  },

  openChoiceModal({ title, description = "", options = [] }) {
    document.getElementById("choiceModalTitle").textContent = title;
    document.getElementById("choiceModalDesc").textContent = description;
    const body = document.getElementById("choiceModalBody");
    body.innerHTML = "";

    options.forEach((opt) => {
      const btn = document.createElement("button");
      btn.className = "choice-option-btn";
      const lbl = document.createElement("span");
      lbl.textContent = opt.label;
      const hint = document.createElement("span");
      hint.className = "muted";
      hint.textContent = opt.hint || "";
      btn.append(lbl, hint);
      btn.onclick = () => {
        this.closeChoiceModal();
        if (opt.onSelect) opt.onSelect();
      };
      body.appendChild(btn);
    });

    document.getElementById("choiceModal").classList.remove("hidden");
  },

  closeChoiceModal() {
    document.getElementById("choiceModal").classList.add("hidden");
  },

  setGoalBadge(stateText, cls = "") {
    const b = document.getElementById("goalBadge");
    b.textContent = `Goal: Step ${this.goalStep} (${stateText})`;
    b.className = `badge goal ${cls}`;
  },

  setStage(stage) {
    this.stage = stage;
    const promptCard = document.getElementById("stagePromptCard");
    const pasteCard = document.getElementById("stagePasteCard");
    const switchBtn = document.getElementById("switchToPasteBtn");

    if (stage === "goal") {
      promptCard.classList.remove("hidden");
      pasteCard.classList.add("hidden");
      if (this.goalStep > 1 || document.getElementById("generatedPrompt").value.trim()) {
        switchBtn.classList.remove("hidden");
      } else {
        switchBtn.classList.add("hidden");
      }
    } else {
      promptCard.classList.add("hidden");
      pasteCard.classList.remove("hidden");
      const pasteArea = document.getElementById("pasteInputArea");
      const doneActions = document.getElementById("doneActions");
      if (this.goalFinished) {
        pasteArea.classList.add("hidden");
        doneActions.classList.remove("hidden");
      } else {
        pasteArea.classList.remove("hidden");
        doneActions.classList.add("hidden");
      }
    }
  },

  togglePromptPreview() {
    document.getElementById("promptPreviewWrap").classList.toggle("hidden");
  },

  resetGoal() {
    this.goalStep = 1;
    this.goalFinished = false;
    this.appliedLog = [];
    this.pendingQuestions = [];
    this.planTasks = [];
    this.selected.clear();

    document.getElementById("task").value = "";
    document.getElementById("generatedPrompt").value = "";
    document.getElementById("promptMeta").textContent = "";
    document.getElementById("copyButtons").innerHTML = "";
    document.getElementById("questionsOut").innerHTML = "";
    document.getElementById("diffOut").innerHTML = "";
    document.getElementById("aiResponse").value = "";
    document.getElementById("applyMeta").textContent = "";
    document.getElementById("promptPreviewWrap").classList.add("hidden");

    const autoPasteChk = document.getElementById("autoProcessPaste");
    const applyBtn = document.getElementById("applyBtn");
    if (applyBtn && autoPasteChk) {
      applyBtn.classList.toggle("hidden", autoPasteChk.checked);
    }

    this.renderPlan([]);
    this.renderFiles();
    this.renderChips();
    this.setGoalBadge("IDLE");
    this.setStage("goal");
    this.showPopup({
      type: "info",
      title: "Ready for a New Goal",
      message: "Describe what you want to build or fix, or double-click any file on the left to inspect/edit.",
    });
  },

  async loadFiles() {
    const res = await fetch("/api/files");
    const data = await res.json();
    this.files = data.files || [];
    this.renderFiles();
  },

  async setProject(customPath = null) {
    const path = customPath !== null ? customPath : document.getElementById("projPath").value;
    const res = await fetch("/api/project", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path }),
    });
    const data = await res.json();
    if (!res.ok) return this.toast(data.error);
    document.getElementById("projPath").value = data.root;
    this.expandedDirs.clear();
    this.resetGoal();
    await this.loadFiles();
    this.toast("Project loaded");
  },

  async smartSelect() {
    if (this.goalFinished) return;
    const task = document.getElementById("task").value.trim();
    if (!task) return this.toast("Enter a task first so Smart Select can match files.");
    const res = await fetch("/api/smart_select", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ task }),
    });
    const data = await res.json();
    this.selected.clear();
    (data.selected || []).forEach((s) => {
      this.selected.set(s.path, { path: s.path, mode: s.mode, start: "", end: "", tokens: s.tokens || 500 });
    });
    this.renderFiles();
    this.renderChips();
    this.toast(`Smart Select picked ${this.selected.size} file(s)`);
  },

  async openBrowser() {
    document.getElementById("browserModal").classList.remove("hidden");
    await this.browseTo(document.getElementById("projPath").value);
  },

  closeBrowser() {
    document.getElementById("browserModal").classList.add("hidden");
  },

  async browseTo(path) {
    const res = await fetch(`/api/browse?path=${encodeURIComponent(path || "")}`);
    const data = await res.json();
    document.getElementById("browsePath").value = data.current;
    this.browseParent = data.parent || "";
    document.getElementById("upBtn").disabled = !this.browseParent;

    const drives = document.getElementById("driveBar");
    drives.innerHTML = "";
    (data.drives || []).forEach((d) => {
      const b = document.createElement("button");
      b.className = "btn ghost";
      b.textContent = d;
      b.onclick = () => this.browseTo(d);
      drives.appendChild(b);
    });

    const list = document.getElementById("dirList");
    list.innerHTML = "";
    (data.dirs || []).forEach((d) => {
      const row = document.createElement("div");
      row.className = "fitem";
      row.textContent = "📁 " + d.name;
      row.onclick = () => this.browseTo(d.path);
      list.appendChild(row);
    });
  },

  browseUp() {
    if (this.browseParent) this.browseTo(this.browseParent);
  },

  async selectBrowsed() {
    const chosen = document.getElementById("browsePath").value;
    this.closeBrowser();
    await this.setProject(chosen);
  },

  buildFileTree(files) {
    const root = { name: "", path: "", folders: new Map(), files: [] };
    files.forEach((f) => {
      const parts = f.path.split("/");
      let node = root;
      for (let i = 0; i < parts.length - 1; i++) {
        const seg = parts[i];
        const nextPath = node.path ? `${node.path}/${seg}` : seg;
        if (!node.folders.has(seg)) {
          node.folders.set(seg, { name: seg, path: nextPath, folders: new Map(), files: [] });
        }
        node = node.folders.get(seg);
      }
      node.files.push({ ...f, name: parts[parts.length - 1] });
    });
    return root;
  },

  collectFolderFiles(node, acc = []) {
    node.files.forEach((f) => acc.push(f));
    node.folders.forEach((sub) => this.collectFolderFiles(sub, acc));
    return acc;
  },

  renderTreeNode(node, container, isFilterActive) {
    const sortedFolders = Array.from(node.folders.values()).sort((a, b) => a.name.localeCompare(b.name));
    sortedFolders.forEach((folder) => {
      const descendantFiles = this.collectFolderFiles(folder, []);
      if (!descendantFiles.length) return;

      const wrap = document.createElement("div");
      wrap.className = "tree-folder";

      const row = document.createElement("div");
      row.className = "tree-row";

      const isCollapsed = !isFilterActive && !this.expandedDirs.has(folder.path);
      const caret = document.createElement("span");
      caret.className = "tree-caret";
      caret.textContent = isCollapsed ? "▸" : "▾";

      const cb = document.createElement("input");
      cb.type = "checkbox";
      const selectedCount = descendantFiles.filter((f) => this.selected.has(f.path)).length;
      cb.checked = selectedCount > 0 && selectedCount === descendantFiles.length;
      cb.indeterminate = selectedCount > 0 && selectedCount < descendantFiles.length;
      cb.onclick = (e) => e.stopPropagation();
      cb.onchange = () => {
        descendantFiles.forEach((f) => {
          if (cb.checked) {
            const mode = f.est_tokens > 4000 ? "outline" : "full";
            this.selected.set(f.path, { path: f.path, mode, start: "", end: "", tokens: f.est_tokens });
          } else {
            this.selected.delete(f.path);
          }
        });
        this.renderFiles();
        this.renderChips();
      };

      const lbl = document.createElement("span");
      lbl.className = "tree-folder-lbl";
      lbl.textContent = `📁 ${folder.name}`;

      row.onclick = () => {
        if (this.expandedDirs.has(folder.path)) {
          this.expandedDirs.delete(folder.path);
        } else {
          this.expandedDirs.add(folder.path);
        }
        this.renderFiles();
      };

      row.append(caret, cb, lbl);
      wrap.appendChild(row);

      const childrenBox = document.createElement("div");
      childrenBox.className = `tree-children${isCollapsed ? " collapsed" : ""}`;
      this.renderTreeNode(folder, childrenBox, isFilterActive);
      wrap.appendChild(childrenBox);
      container.appendChild(wrap);
    });

    const sortedFiles = [...node.files].sort((a, b) => a.name.localeCompare(b.name));
    sortedFiles.forEach((f) => {
      const row = document.createElement("div");
      row.className = "tree-row";
      row.title = "Double-click to view or edit file";

      const spacer = document.createElement("span");
      spacer.className = "tree-caret";
      spacer.textContent = "";

      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.checked = this.selected.has(f.path);
      cb.onclick = (e) => e.stopPropagation();
      cb.onchange = () => {
        if (cb.checked) {
          const defaultMode = f.est_tokens > 4000 ? "outline" : "full";
          this.selected.set(f.path, { path: f.path, mode: defaultMode, start: "", end: "", tokens: f.est_tokens });
        } else {
          this.selected.delete(f.path);
        }
        this.renderFiles();
        this.renderChips();
      };

      const name = document.createElement("span");
      name.className = "tree-file-lbl";
      name.textContent = f.name;

      const meta = document.createElement("span");
      meta.className = "fmeta";
      meta.textContent = `~${f.est_tokens}t`;

      row.onclick = () => {
        cb.checked = !cb.checked;
        cb.onchange();
      };
      row.ondblclick = (e) => {
        e.stopPropagation();
        this.openEditor(f.path);
      };

      row.append(spacer, cb, name, meta);
      container.appendChild(row);
    });
  },

  renderFiles() {
    const q = document.getElementById("filter").value.toLowerCase().trim();
    const list = document.getElementById("fileList");
    list.innerHTML = "";

    const filtered = q
      ? this.files.filter((f) => f.path.toLowerCase().includes(q))
      : this.files;

    const tree = this.buildFileTree(filtered);
    this.renderTreeNode(tree, list, Boolean(q));
    this.updateStats();
  },

  renderChips() {
    const box = document.getElementById("selectedChips");
    box.innerHTML = "";
    this.selected.forEach((spec, path) => {
      const chip = document.createElement("div");
      chip.className = "chip";
      const lbl = document.createElement("span");
      lbl.textContent = path;

      const modeBtn = document.createElement("button");
      modeBtn.className = "btn ghost";
      modeBtn.style.padding = "2px 8px";
      modeBtn.style.fontSize = "11px";
      modeBtn.textContent = `${spec.mode} ▾`;
      modeBtn.onclick = () => {
        this.openChoiceModal({
          title: `Context Mode for ${path}`,
          description: "Choose how much of this file to include in the AI prompt:",
          options: [
            {
              label: "Full File",
              hint: `~${spec.tokens} tokens`,
              onSelect: () => {
                spec.mode = "full";
                this.renderChips();
                this.updateStats();
                this.toast(`${path} set to full mode`);
              },
            },
            {
              label: "Outline Only (Save ~80% Tokens)",
              hint: `~${Math.round(spec.tokens * 0.2)} tokens`,
              onSelect: () => {
                spec.mode = "outline";
                this.renderChips();
                this.updateStats();
                this.toast(`${path} set to outline mode`);
              },
            },
            {
              label: "Specific Line Range",
              hint: "Choose start & end lines",
              onSelect: () => {
                spec.mode = "range";
                this.renderChips();
                this.updateStats();
              },
            },
            {
              label: "Remove File from Selection",
              hint: "Exclude",
              onSelect: () => {
                this.selected.delete(path);
                this.renderFiles();
                this.renderChips();
              },
            },
          ],
        });
      };
      chip.append(lbl, modeBtn);

      if (spec.mode === "range") {
        const sIn = document.createElement("input");
        sIn.className = "rng";
        sIn.placeholder = "start";
        sIn.value = spec.start;
        sIn.oninput = () => (spec.start = parseInt(sIn.value) || "");
        const eIn = document.createElement("input");
        eIn.className = "rng";
        eIn.placeholder = "end";
        eIn.value = spec.end;
        eIn.oninput = () => (spec.end = parseInt(eIn.value) || "");
        chip.append(sIn, eIn);
      }
      box.appendChild(chip);
    });
  },

  updateStats() {
    document.getElementById("fileStats").textContent = `${this.selected.size} / ${this.files.length} files`;
    let total = 0;
    this.selected.forEach((s) => {
      total += s.mode === "outline" ? Math.round(s.tokens * 0.2) : s.tokens;
    });
    document.getElementById("selectedTokens").textContent = `~${total.toLocaleString()} tokens`;
  },

  toggleAll(on) {
    const q = document.getElementById("filter").value.toLowerCase();
    this.files.forEach((f) => {
      if (!q || f.path.toLowerCase().includes(q)) {
        if (on) {
          const mode = f.est_tokens > 4000 ? "outline" : "full";
          this.selected.set(f.path, { path: f.path, mode, start: "", end: "", tokens: f.est_tokens });
        } else {
          this.selected.delete(f.path);
        }
      }
    });
    this.renderFiles();
    this.renderChips();
  },

  collectAnswers() {
    const answers = [];
    this.pendingQuestions.forEach((q, idx) => {
      const checked = document.querySelector(`input[name="qa_${idx}"]:checked`);
      const custom = document.getElementById(`qa_custom_${idx}`).value.trim();
      const ans = custom || (checked ? checked.value : "");
      if (ans) answers.push({ question: q.question, answer: ans });
    });
    return answers;
  },

  renderPlan(planItems) {
    const panel = document.getElementById("planPanel");
    const box = document.getElementById("planOut");
    const meta = document.getElementById("planMeta");

    if (planItems && planItems.length) {
      this.planTasks = planItems;
    }

    if (!this.planTasks.length) {
      panel.classList.add("hidden");
      panel.open = false;
      box.innerHTML = "";
      return;
    }

    panel.classList.remove("hidden");
    box.innerHTML = "";
    let totalCount = 0;
    let doneCount = 0;

    this.planTasks.forEach((item) => {
      totalCount += 1;
      if (item.done) doneCount += 1;

      const wrap = document.createElement("div");
      wrap.className = "plan-item";

      const mainRow = document.createElement("label");
      mainRow.className = "plan-main";
      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.style.width = "auto";
      cb.checked = Boolean(item.done);
      const txt = document.createElement("span");
      txt.textContent = item.text;
      if (item.done) txt.className = "plan-done";
      cb.onchange = () => {
        item.done = cb.checked;
        txt.className = cb.checked ? "plan-done" : "";
      };
      mainRow.append(cb, txt);
      wrap.appendChild(mainRow);

      if (item.subtasks && item.subtasks.length) {
        const subBox = document.createElement("div");
        subBox.className = "plan-sublist";
        item.subtasks.forEach((sub) => {
          totalCount += 1;
          if (sub.done) doneCount += 1;
          const subRow = document.createElement("label");
          subRow.className = "plan-sub";
          const scb = document.createElement("input");
          scb.type = "checkbox";
          scb.style.width = "auto";
          scb.checked = Boolean(sub.done);
          const stxt = document.createElement("span");
          stxt.textContent = sub.text;
          if (sub.done) stxt.className = "plan-done";
          scb.onchange = () => {
            sub.done = scb.checked;
            stxt.className = scb.checked ? "plan-done" : "";
          };
          subRow.append(scb, stxt);
          subBox.appendChild(subRow);
        });
        wrap.appendChild(subBox);
      }
      box.appendChild(wrap);
    });

    meta.textContent = `${doneCount}/${totalCount} completed (click to expand)`;
  },

  async buildPrompt(isAutoNext = false) {
    const task = document.getElementById("task").value.trim();
    if (!task) return this.toast("Describe your goal first.");

    this.goalFinished = false;

    if (
      !isAutoNext &&
      this.goalStep === 1 &&
      this.selected.size === 0 &&
      document.getElementById("autoSelectSmart").checked
    ) {
      await this.smartSelect();
    }

    const include_tree = document.getElementById("includeTree").checked;
    const chunk_size = parseInt(document.getElementById("chunkSize").value) || 120000;
    const files = Array.from(this.selected.values());
    const answers = this.collectAnswers();

    const res = await fetch("/api/build_prompt", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        task,
        files,
        include_tree,
        chunk_size,
        goal_step: this.goalStep,
        answers,
        applied_log: this.appliedLog,
      }),
    });
    const data = await res.json();
    document.getElementById("generatedPrompt").value = data.full_prompt;
    document.getElementById("promptMeta").textContent =
      `${data.chars.toLocaleString()} chars (~${data.est_tokens.toLocaleString()} tokens)`;

    const btns = document.getElementById("copyButtons");
    btns.innerHTML = "";
    data.parts.forEach((part, idx) => {
      const b = document.createElement("button");
      b.className = "btn success";
      const label = data.parts.length === 1 ? "Copy Prompt" : `Copy Part ${idx + 1}/${data.parts.length}`;
      b.textContent = label;
      b.onclick = async () => {
        await navigator.clipboard.writeText(part);
        this.toast(`${label} copied!`);
        if (document.getElementById("autoUnselect").checked) {
          this.selected.clear();
          this.renderFiles();
          this.renderChips();
        }
      };
      btns.appendChild(b);
    });

    const triggerAiHandoffPopup = (copiedOk) => {
      const firstLabel = data.parts.length === 1 ? "Prompt" : `Part 1/${data.parts.length}`;
      this.showPopup({
        type: "red",
        title: copiedOk
          ? `${firstLabel} Copied — Go Paste in AI & Copy Reply`
          : "Prompt Ready — Copy & Paste in AI Chat",
        message: "1) Paste the prompt into your AI chat. 2) Copy the AI's response. 3) Click Done below to auto-apply and advance.",
        actions: [
          {
            label: "Copy Prompt Again",
            cls: "ghost",
            onClick: async () => {
              await navigator.clipboard.writeText(data.parts[0]);
              triggerAiHandoffPopup(true);
            },
          },
          {
            label: "Done (Paste & Run Next Step)",
            cls: "danger",
            onClick: async () => {
              const aiBox = document.getElementById("aiResponse");
              this.setStage("paste");
              try {
                const clipText = await navigator.clipboard.readText();
                if (clipText && clipText.trim() && clipText.trim() !== data.parts[0].trim()) {
                  aiBox.value = clipText;
                  await this.runOps(true);
                  return;
                }
              } catch (e) {
                // Fallback if clipboard read permission is blocked
              }
              if (aiBox.value.trim()) {
                await this.runOps(true);
              } else {
                aiBox.focus();
                this.showPopup({
                  type: "red",
                  title: "Paste AI Response Below",
                  message: "Press Ctrl+V inside the response box (or copy the AI reply first and click Done again).",
                });
              }
            },
          },
        ],
      });
    };

    if (data.parts && data.parts.length > 0) {
      try {
        await navigator.clipboard.writeText(data.parts[0]);
        if (document.getElementById("autoUnselect").checked) {
          this.selected.clear();
          this.renderFiles();
          this.renderChips();
        }
        triggerAiHandoffPopup(true);
      } catch (e) {
        triggerAiHandoffPopup(false);
      }
    }

    this.setGoalBadge("WAITING REPLY", "active");
    this.setStage("paste");
  },

  renderQuestions(questions) {
    this.pendingQuestions = questions || [];
    const box = document.getElementById("questionsOut");
    box.innerHTML = "";
    if (!this.pendingQuestions.length) return;

    this.pendingQuestions.forEach((q, idx) => {
      const card = document.createElement("div");
      card.className = "qa-card";
      const title = document.createElement("div");
      title.className = "qa-title";
      title.textContent = q.question;
      card.appendChild(title);

      (q.options || []).forEach((opt) => {
        const lbl = document.createElement("label");
        lbl.className = "qa-opt";
        const r = document.createElement("input");
        r.type = "radio";
        r.name = `qa_${idx}`;
        r.value = opt;
        r.onchange = () => {
          if (this.pendingQuestions.length === 1) {
            this.submitAnswersAndAdvance();
          }
        };
        lbl.append(r, document.createTextNode(opt));
        card.appendChild(lbl);
      });

      const custom = document.createElement("input");
      custom.id = `qa_custom_${idx}`;
      custom.placeholder = "Or type a custom answer and press Enter...";
      custom.onkeydown = (e) => {
        if (e.key === "Enter") {
          e.preventDefault();
          this.submitAnswersAndAdvance();
        }
      };
      card.appendChild(custom);
      box.appendChild(card);
    });

    const submitRow = document.createElement("div");
    submitRow.className = "row";
    const btn = document.createElement("button");
    btn.className = "btn primary";
    btn.textContent = "Send Answers & Copy Next Prompt →";
    btn.onclick = () => this.submitAnswersAndAdvance();
    submitRow.appendChild(btn);
    box.appendChild(submitRow);
  },

  async submitAnswersAndAdvance() {
    this.goalStep += 1;
    await this.buildPrompt(true);
    document.getElementById("aiResponse").value = "";
    this.renderQuestions([]);
    this.toast(`Step ${this.goalStep} prompt with answers copied!`);
  },

  async runOps(apply) {
    const text = document.getElementById("aiResponse").value;
    let fallback_path = document.getElementById("fallbackFile").value.trim();
    if (!fallback_path && this.selected.size === 1) {
      fallback_path = Array.from(this.selected.keys())[0];
    }

    const res = await fetch("/api/apply", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text, apply, fallback_path }),
    });
    const data = await res.json();

    if (data.plan && data.plan.length) {
      this.renderPlan(data.plan);
    }

    const hasQuestions = (data.questions || []).length > 0;
    const hasNeedFiles = (data.need_files || []).length > 0;

    this.renderQuestions(data.questions || []);

    const out = document.getElementById("diffOut");
    out.innerHTML = "";
    const results = data.results || [];
    document.getElementById("applyMeta").textContent =
      `${results.length} edit(s) · ${(data.need_files || []).length} file req(s) · ${(data.questions || []).length} question(s)`;

    let appliedCount = 0;
    let errorCount = 0;
    results.forEach((r) => {
      const isApplied = apply && r.status === "applied";
      const card = document.createElement("details");
      card.className = "diff-file";
      card.open = !isApplied;

      const hdr = document.createElement("summary");
      hdr.className = `diff-header ${r.status}`;
      hdr.style.cursor = "pointer";
      hdr.textContent = `${isApplied ? "▸" : "▾"} [${r.status.toUpperCase()}] ${r.path}`;
      card.ontoggle = () => {
        hdr.textContent = `${card.open ? "▾" : "▸"} [${r.status.toUpperCase()}] ${r.path}`;
      };
      card.appendChild(hdr);

      const body = document.createElement("div");
      body.className = "diff-body";
      if (r.message) {
        const line = document.createElement("div");
        line.className = "dline del";
        line.textContent = r.message;
        body.appendChild(line);
      } else if (r.diff_lines && r.diff_lines.length) {
        r.diff_lines.forEach((dl) => {
          const line = document.createElement("div");
          line.className = `dline ${dl.kind}`;
          line.textContent = dl.text;
          body.appendChild(line);
        });
      } else {
        const line = document.createElement("div");
        line.className = "dline meta";
        line.textContent = "(no text changes)";
        body.appendChild(line);
      }
      card.appendChild(body);
      out.appendChild(card);

      if (isApplied) {
        appliedCount += 1;
        this.appliedLog.push(`Step ${this.goalStep}: updated ${r.path}`);
      } else if (r.status === "error") {
        errorCount += 1;
      }
    });

    const applyBtn = document.getElementById("applyBtn");
    if (applyBtn) {
      const autoOn = document.getElementById("autoProcessPaste").checked;
      applyBtn.classList.toggle("hidden", autoOn && appliedCount > 0 && errorCount === 0);
    }

    if (apply && appliedCount > 0) {
      await this.loadFiles();
    }

    // Handle AI-requested files automatically
    if (hasNeedFiles) {
      data.need_files.forEach((nf) => {
        const match = this.files.find((f) => f.path === nf.path);
        this.selected.set(nf.path, {
          path: nf.path,
          mode: nf.mode || "full",
          start: nf.start || "",
          end: nf.end || "",
          tokens: match ? match.est_tokens : 500,
        });
      });
      this.renderFiles();
      this.renderChips();

      if (!hasQuestions) {
        this.goalStep += 1;
        await this.buildPrompt(true);
        document.getElementById("aiResponse").value = "";
        this.setGoalBadge("WAITING NEXT", "active");
        this.toast(`Step ${this.goalStep}: copied ${data.need_files.length} requested file(s)!`);
        return;
      }
    }

    // Automatically advance to next step when AI indicates APPLIED_NEXT
    if (apply && data.status_flag === "APPLIED_NEXT" && !hasQuestions && errorCount === 0) {
      this.goalStep += 1;
      await this.buildPrompt(true);
      document.getElementById("aiResponse").value = "";
      this.setGoalBadge("WAITING NEXT", "active");
      this.toast(`Applied ${appliedCount} file(s) & copied Step ${this.goalStep} prompt!`);
      return;
    }

    if (data.status_flag === "DONE") {
      this.goalFinished = true;
      this.selected.clear();
      this.renderFiles();
      this.renderChips();
      this.setGoalBadge("DONE", "done");
      this.setStage("paste");
      this.showPopup({
        type: "success",
        title: "Goal Completed!",
        message: appliedCount > 0
          ? `Successfully applied ${appliedCount} file(s). Expand any file below to review its diff.`
          : "All steps for this goal are complete.",
        actions: [
          {
            label: "Start New Goal",
            cls: "success",
            onClick: () => this.resetGoal(),
          },
        ],
      });
    } else if (hasQuestions || data.status_flag === "NEED_MORE" || data.status_flag === "APPLIED_NEXT") {
      this.setGoalBadge("WAITING INPUT", "active");
      if (hasQuestions) {
        this.showPopup({
          type: "info",
          title: "AI Needs Your Input",
          message: "Choose an option below (or type a custom answer) to generate and copy the next prompt.",
        });
      }
    } else if (apply && appliedCount > 0) {
      this.showPopup({
        type: "success",
        title: `Applied ${appliedCount} File(s)`,
        message: "Changes saved to disk. Expand any file below to inspect the diff.",
      });
    } else if (errorCount > 0) {
      this.showPopup({
        type: "red",
        title: "Patch Error",
        message: "One or more edits could not be applied. Check the details below.",
      });
    }
  },

  // Code Editor Modal
  async openEditor(relPath) {
    const res = await fetch(`/api/file?path=${encodeURIComponent(relPath)}`);
    const data = await res.json();
    if (!res.ok) return this.toast(data.error || "Failed to open file");

    this.editingPath = relPath;
    document.getElementById("editorTitle").textContent = relPath;
    const ext = relPath.includes(".") ? relPath.split(".").pop().toUpperCase() : "TEXT";
    document.getElementById("editorLangBadge").textContent = ext;

    const area = document.getElementById("editorCode");
    area.value = data.content;
    this.syncEditorGutter();
    document.getElementById("editorModal").classList.remove("hidden");
    area.focus();
  },

  closeEditor() {
    document.getElementById("editorModal").classList.add("hidden");
    this.editingPath = "";
  },

  syncEditorGutter() {
    const area = document.getElementById("editorCode");
    const gutter = document.getElementById("editorLines");
    const lineCount = (area.value.match(/\n/g) || []).length + 1;
    const nums = [];
    for (let i = 1; i <= lineCount; i++) nums.push(i);
    gutter.textContent = nums.join("\n");
  },

  syncEditorScroll() {
    const area = document.getElementById("editorCode");
    const gutter = document.getElementById("editorLines");
    gutter.scrollTop = area.scrollTop;
  },

  prettifyEditor() {
    const area = document.getElementById("editorCode");
    const ext = this.editingPath.split(".").pop().toLowerCase();
    try {
      if (ext === "json") {
        area.value = JSON.stringify(JSON.parse(area.value), null, 2);
        this.syncEditorGutter();
        return this.toast("Formatted JSON");
      }
      // Clean trailing spaces, normalize tabs to 2/4 spaces, and ensure single trailing newline
      const indent = ext === "py" ? "    " : "  ";
      const cleaned = area.value
        .replace(/\r\n/g, "\n")
        .split("\n")
        .map((line) => line.replace(/\t/g, indent).replace(/[ \t]+$/, ""))
        .join("\n")
        .replace(/\n{3,}/g, "\n\n")
        .trimEnd() + "\n";
      area.value = cleaned;
      this.syncEditorGutter();
      this.toast("Prettified whitespace & indentation");
    } catch (e) {
      this.toast(`Format error: ${e.message}`);
    }
  },

  async saveEditor() {
    if (!this.editingPath) return;
    const content = document.getElementById("editorCode").value;
    const res = await fetch("/api/file", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path: this.editingPath, content }),
    });
    const data = await res.json();
    if (!res.ok) return this.toast(data.error || "Save failed");
    await this.loadFiles();
    this.toast(`Saved ${this.editingPath}`);
  },

  init() {
    // Clear browser-restored form inputs on page reload so Smart Select never auto-picks stale goals
    document.getElementById("task").value = "";
    document.getElementById("aiResponse").value = "";
    document.getElementById("generatedPrompt").value = "";
    document.getElementById("fallbackFile").value = "";
    this.setStage("goal");

    const autoPasteChk = document.getElementById("autoProcessPaste");
    const applyBtn = document.getElementById("applyBtn");
    const syncApplyBtnVisibility = () => {
      if (applyBtn) applyBtn.classList.toggle("hidden", autoPasteChk.checked);
    };
    syncApplyBtnVisibility();
    autoPasteChk.addEventListener("change", syncApplyBtnVisibility);

    const aiBox = document.getElementById("aiResponse");
    aiBox.addEventListener("paste", () => {
      if (!autoPasteChk.checked) return;
      setTimeout(() => {
        if (aiBox.value.trim()) this.runOps(true);
      }, 60);
    });

    const taskBox = document.getElementById("task");
    let smartTimer = null;
    taskBox.addEventListener("input", () => {
      if (this.goalFinished) this.goalFinished = false;
      if (!document.getElementById("autoSelectSmart").checked) return;
      clearTimeout(smartTimer);
      smartTimer = setTimeout(() => {
        if (
          this.stage === "goal" &&
          !this.goalFinished &&
          this.goalStep === 1 &&
          taskBox.value.trim().length >= 8 &&
          this.selected.size === 0
        ) {
          this.smartSelect();
        }
      }, 650);
    });

    const editorArea = document.getElementById("editorCode");
    editorArea.addEventListener("keydown", (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "s") {
        e.preventDefault();
        this.saveEditor();
      } else if (e.key === "Tab") {
        e.preventDefault();
        const start = editorArea.selectionStart;
        const end = editorArea.selectionEnd;
        const indent = this.editingPath.endsWith(".py") ? "    " : "  ";
        editorArea.value = editorArea.value.substring(0, start) + indent + editorArea.value.substring(end);
        editorArea.selectionStart = editorArea.selectionEnd = start + indent.length;
        this.syncEditorGutter();
      }
    });
  },
};

App.init();
App.loadFiles();

const App = {
  files: [],
  selected: new Map(), // path -> { path, mode, start, end, tokens }
  expandedDirs: new Set(),
  browseParent: "",
  goalStep: 1,
  goalFinished: false,
  stage: "goal", // "goal" | "paste"
  appliedLog: [],
  pendingQuestions: [],
  planTasks: [],
  editingPath: "",

  showPopup({ type = "info", title = "", message = "", actions = [] }) {
    const box = document.getElementById("inlinePopup");
